import Foundation

private typealias E = EvidenceSeed

/// Follow-up trials for the batch AN everyday-crime stories.
extension FollowUpCases {
    static let batchAN: [CaseTemplate] = [barcodeSwapTwo, mopedNoLicense, partyResisting, dirtBikeLawn, schoolWallPaint, falseAlarmTwo, badgeObstruction, pistolInTruck, secondDogChained, bumperAgain, badCheckHardware, threatByText, stalkingAtWork, drunkPorchTwo, mailCardOpen, siphonTwo, windshieldCrack, tailgateThreat, falseNameResisting, copperScrapYard, laptopPhoneTwo, returnFraudTwo, fakeLicenseBar, paintCansTwo, dumpsterFireTwo, cashBoxCafe, shedBreakInTwo, scaleAgain, airsoftSchoolLot]

    static let barcodeSwapTwo = SmallCases.make(
        key: "story.followup.barcodeSwapTwo",
        category: .property,
        headlines: ["Shopper Swapped Barcode Labels at Big Box Store", "Second Price Tag Charge for Defendant From Hardware Case"],
        law: "larcenyMerchant",
        threshold: 6,
        spec: "Stole $318 in merchandise from a retail merchant by switching labels, on {DATE}.",
        ages: 24...66,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} was seen at a big box store sticking a $9 barcode on a $318 electric grill and paying at self-checkout. Loss prevention stopped {DL} in the lot. {D.He} says the self-checkout scanned the wrong item.",
        state: [E(.video, 3, "Self-Checkout Camera", "{D} places a sticker on the grill box and scans it as a $9 item."), E(.document, 2, "Receipt", "One item, $9, for a $318 grill.")],
        defense: [E(.statement, 1, "Scanner", "{DL} says the scanner mis-read the label.")],
        role: "Big box store loss prevention manager",
        exam: [.direct("What is your position at the store?", "\"I am the loss prevention manager at a big box store. I watch the floor and the self-checkout lanes, and I review video when something looks wrong.\""),
               .direct("What drew your attention to {DL}?", "\"{D.He} had an electric grill in a cart and stopped at the end of a self-checkout lane for longer than anyone needs to. I moved to a spot where I could see the screen and the box.\""),
               .direct("What did you see {DL} do?", "\"{D.He} took a small sticker from a pocket and pressed it over the barcode on the grill box. Then {D.he} scanned the box as if nothing had happened.\""),
               .direct("What did the item scan as?", "\"A $9 clip pack, according to the register tape. The grill is a $318 electric model, so the difference was $309.\""),
               .direct("What does the self-checkout camera show?", "\"It shows {DL}'s hands placing the sticker and then scanning the box. You can see the sticker go on in the clip, and the scan follows about ten seconds later.\""),
               .direct("What did you do next?", "\"I let {D.him} pay and walk out, because that is our policy, and then I stopped {D.him} in the parking lot. I identified myself and asked {D.him} to come back inside.\""),
               .direct("How did {DL} react?", "\"{D.He} was calm and did not run. {D.He} said the self-checkout had scanned the wrong item, and I said I had watched {D.him} place the sticker.\""),
               .cross("The scanner might have misread the label, mightn't it?", "\"Scanners do make mistakes. But the video shows a sticker going onto the box before the scan, and I do not see how a scanner puts a sticker on a box.\""),
               .cross("Did {DL} try to run when you stopped {D.him}?", "\"No, {D.he} did not run or argue. {D.He} walked back inside with me and sat in the office until the deputy came.\""),
               .cross("Did the store's scanner mis-read any other items that week?", "\"I have heard that it mis-read a couple of items for other customers. I would have to check the logs, and I did not review that before today.\""),
               .cross("Was a sticker found on the grill box?", "\"Yes, I peeled one off the box. It was a printed barcode label for the clip pack, and it was not a store label.\""),
               .cross("You did not see where the sticker came from, did you?", "\"No, I saw it come out of a pocket. I did not see {D.him} print it or buy it.\"")],
        theory: ("{D} stuck a $9 barcode on a $318 grill and paid at self-checkout, again, at a bigger store.", "{D} paid what a self-checkout scanner charged and never touched a sticker."),
        allocution: "\"I've learned my lesson, and I'm sorry to that store. That grill was on sale as far as I knew, and I paid at the self-checkout and didn't notice the wrong item scanned. I've been in this courtroom before, and I know this looks like a pattern. I'll pay the difference.\"",
        truths: ("{DL} had printed barcode stickers at home.", "The store's scanner had mis-read two other customers' items that week."),
        defendant: [.direct("Did you put a sticker on that grill box?", "\"No, I did not. I never touched a sticker on that box, and I do not carry stickers around with me.\""),
               .direct("Why were you buying that grill?", "\"It was on sale as far as I knew. I had seen the sale tag on the shelf and I wanted it for a family cookout.\""),
               .direct("What happened at the self-checkout?", "\"I scanned the box and paid what the screen told me. I did not look closely at the item name on the screen, and I did not notice the wrong item.\""),
               .direct("How did you feel when the manager stopped you in the lot?", "\"Shocked and embarrassed. I told the manager the scanner had read the wrong thing, and I offered to pay the difference right there.\""),
               .direct("What did you do inside?", "\"I sat in the office and waited. I answered every question and I did not try to leave.\""),
               .direct("What do you want the store to know?", "\"I am sorry for the trouble. I will pay the difference, and I will check every screen from now on.\""),
               .cross("The video shows a sticker going onto the box, doesn't it?", "\"I know that is what the manager says it shows. I have seen the clip, and I cannot explain what is on the box.\""),
               .cross("You were here before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"Yes, and I know this looks like a pattern. I have learned my lesson, and I did not do this.\""),
               .cross("You printed barcode stickers at home, didn't you?", "\"I printed labels for my own shelves at home, but I did not print one for that grill.\""),
               .cross("The receipt shows one item for $9, doesn't it?", "\"Yes, and I did not look at it before I left. That was careless of me.\""),
               .cross("A $9 total for a $318 grill should have looked wrong to you, shouldn't it?", "\"It should have, and I did not notice. I was in a hurry, and I paid what the screen said.\"")],
        openings: ("Loss prevention watched {D} place a sticker over the barcode on a $318 electric grill and scan it at self-checkout as a $9 clip pack. {DL} came before this court in {PRIORDATE} over {PRIOR}, and the self-checkout camera records the sticker going on.", "The defense will present a self-checkout scanner that mis-read other customers' items that same week. A buyer who did not look at a screen is careless, and carelessness is not a theft."),
        closings: ("The same trick, twice: a sticker over a barcode and a $309 difference that never reached the register. The camera shows the sticker going on, and {D} had been here before for it.", "A scanner that mis-read items that week, a shopper who did not check the screen, and an offer to pay the difference on the spot. The State has not shown that {D} put that sticker there."),
        timeline: [(0, "Midday: {D} wheels a $318 electric grill to a self-checkout lane."), (0, "The self-checkout camera records a sticker going onto the box before the scan."), (0, "{D} pays $9 and walks out, and loss prevention stops {D} in the parking lot."), (1, "A deputy takes the sticker and the register tape and {D} is charged.")],
        identified: "Loss prevention's review of self-checkout video.",
        genders: ["D": .male])

    static let mopedNoLicense = SmallCases.make(
        key: "story.followup.mopedNoLicense",
        category: .traffic,
        headlines: ["Moped Rider Without License Stopped Again", "Driving While Revoked After Moped Chase"],
        law: "dwlr",
        spec: "Drove a motor vehicle on a public highway while {D.his} driver's license was revoked, on {DATE}.",
        ages: 18...40,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} was stopped on a moped at a checkpoint. {DL}'s license had been revoked after the earlier case. {D.He} says the moped is a bicycle with a motor.",
        state: [E(.document, 3, "DMV Record", "License revoked after the earlier conviction."), E(.video, 2, "Checkpoint Camera", "{D} on the moped, handing over an expired ID.")],
        defense: [E(.statement, 1, "Bicycle", "{DL} says the moped has pedals and a 49 cc engine.")],
        role: "State Highway Patrol trooper",
        exam: [.direct("What is your assignment with the Highway Patrol?", "\"I am a state trooper assigned to this district. I run traffic stops, license checkpoints, and crash scenes, and I have done it for eleven years.\""),
               .direct("What was the checkpoint that morning?", "\"A routine license checkpoint on a county road. We stop every vehicle for a few seconds, check licenses, and look for equipment problems.\""),
               .direct("What did you find when you stopped {DL}?", "\"{D.He} was on a moped, and when I asked for a license, {D.he} handed me an expired ID. I ran the name and found that the license was revoked.\""),
               .direct("Why was the license revoked?", "\"After the earlier case in this court, {DL}'s license was revoked. The DMV record shows the revocation and no limited privilege.\""),
               .direct("What kind of vehicle was it?", "\"A moped with a 49 cc engine and pedals. It is a motor vehicle under the statute because it has an engine and is registered for the road.\""),
               .direct("What did {DL} say?", "\"{D.He} said the moped was just a bicycle with a motor and that {D.he} thought it was different from a car. I explained that the statute says otherwise.\""),
               .direct("How was {DL} with you?", "\"Polite and cooperative. {D.He} did not argue, and {D.he} gave me the key when I asked.\""),
               .cross("It has pedals, doesn't it?", "\"Yes, it does. But pedals do not change what it is, since the statute looks at the engine.\""),
               .cross("Was {DL} told by the court that mopeds count?", "\"I believe the earlier order mentioned motor vehicles generally. I am not sure it mentioned mopeds by name.\""),
               .cross("Did the dealer tell {DL} no license was needed?", "\"I have heard that, but I did not speak with the dealer. It does not change what the statute says.\""),
               .cross("Was {DL} driving erratically?", "\"No, {D.he} was driving normally on the shoulder, and the only violation was the license.\""),
               .cross("You do not know what {DL} believed, do you?", "\"No, I only know what {D.he} told me and what the record shows.\"")],
        theory: ("{D} drove a motor vehicle on a revoked license at a checkpoint.", "{D} believed a moped was a bicycle with a motor and did not need a license."),
        allocution: "\"I thought it was legal, and I'm sorry. That moped looked to me like a bicycle with a motor, and I thought it was different from a car. I know my license was revoked after the earlier case. I'll sell it and wait until I'm allowed to drive again.\"",
        truths: ("{DL} had been told by the court that mopeds count.", "The moped's dealer told {DL} no license was needed."),
        defendant: [.direct("Did you know your license was revoked?", "\"Yes, I knew, and I did not drive a car. I thought the moped was different.\""),
               .direct("Why did you think a moped was different?", "\"It looked to me like a bicycle with a motor, and it has pedals. The dealer told me no license was needed when I bought it.\""),
               .direct("What did the dealer say?", "\"He said a moped under fifty cc does not need a license, and I took his word. I did not read the statute.\""),
               .direct("Did you know about the court's order?", "\"I remember being told the revocation covered driving. I did not remember mopeds being mentioned.\""),
               .direct("Why were you on the road that morning?", "\"I was going to work, and the moped is the only way I have. I did not think about the checkpoint.\""),
               .direct("What will you do now?", "\"I will sell it and wait until I am allowed to drive again. I am sorry for the confusion.\""),
               .cross("You knew your license was revoked when you got on the moped, didn't you?", "\"Yes, I did, and I should have asked someone whether it applied. I assumed it did not.\""),
               .cross("You were here before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"Yes, and I know I should have paid closer attention to what I was doing. I did not want to break the order again.\""),
               .cross("The court told you that mopeds count, didn't it?", "\"I forgot that, and I know that is no excuse. I should have gone back and read the order again before I got on the moped.\""),
               .cross("You handed the trooper an expired ID, didn't you?", "\"Yes, because my ID had run out a few months earlier. I did not think about it until the trooper asked for it.\""),
               .cross("A dealer is not a lawyer, is that right?", "\"No, a dealer is not a lawyer. I should have checked with someone who knew the law before I took the dealer's word for it.\"")],
        openings: ("A trooper stopped {D} on a moped at a license checkpoint, and {D} handed over an expired ID. The DMV record shows {DL}'s license was revoked after the earlier case, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will present a dealer who said no license was needed for a moped and a defendant who truly believed it. A mistake about what counts as a motor vehicle is not a willful violation."),
        closings: ("A revocation on the record, a 49 cc moped with an engine, and a checkpoint where {D} gave an expired ID. {D} had been told what a motor vehicle is.", "A dealer who said no license was needed, a moped that looks like a bicycle, and a defendant who gave the trooper an honest answer. The State has not shown that {D} knew {D.he} was breaking the law."),
        timeline: [(0, "Morning: a license checkpoint runs on a county road."), (0, "The trooper stops {D} on a moped and finds an expired ID."), (0, "The DMV record shows {D}'s license is revoked after the earlier case."), (0, "{D} is cited for driving while license revoked.")],
        identified: "A highway patrol checkpoint.",
        genders: ["D": .male])

    static let partyResisting = SmallCases.make(
        key: "story.followup.partyResisting",
        category: .publicOrder,
        headlines: ["Party Host Resists Deputies, Charged Again", "Resisting Charge After Second Noise Complaint"],
        law: "resisting",
        spec: "Willfully resisted, delayed, and obstructed a public officer, a sheriff's deputy, in discharging a duty of the officer's office, on {DATE}.",
        ages: 21...45,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} hosted another party. When deputies asked {DL} to lower the music, {DL} refused to give a name and walked back into the house. A deputy followed and {DL} pulled away twice.",
        state: [E(.video, 3, "Body Camera", "{D} walks away from the deputy and pulls away from a hand on {D.his} arm."), E(.document, 2, "Complaint Log", "Third noise call at the address in a month.")],
        defense: [E(.statement, 1, "Own Home", "{DL} says {D.he} was in {D.his} own home and didn't have to answer.")],
        role: "Sheriff's deputy",
        exam: [.direct("What is your assignment?", "\"I am a sheriff's deputy on the night shift. I take noise complaints, disturbances, and traffic calls, and I have patrolled this part of the county for eight years.\""),
               .direct("Why were you at {DL}'s address?", "\"We got a noise complaint about loud music at about eleven at night. It was the third call about that address in a month, according to the complaint log.\""),
               .direct("What did you ask {DL} to do?", "\"I asked {D.him} to lower the music and to give me a name for the citation. {D.He} refused to give a name and walked back toward the house.\""),
               .direct("What happened when {DL} walked away?", "\"I followed to finish the citation and put a hand on {D.his} arm. {D.He} pulled the arm away, and then did it a second time.\""),
               .direct("What does the body camera show?", "\"It shows {DL} turning away, walking toward the door, and pulling away when I take hold of the arm. It also shows me following up the steps.\""),
               .direct("Why did you follow {DL}?", "\"I had not completed the citation, and a person who refuses to identify cannot be cited. I also wanted to keep the situation calm.\""),
               .direct("How did the party affect the neighbors?", "\"Several neighbors had called. They said the music had been going every weekend, and they could not sleep.\""),
               .cross("It was {DL}'s own home, wasn't it?", "\"Yes, it was, and I know a person has rights there. I had a lawful reason to speak to {D.him} about the noise.\""),
               .cross("Did you have a warrant to enter the house?", "\"No, I did not have a warrant. I followed {D.him} as far as the front steps.\""),
               .cross("Did {DL} say you could not touch {D.him} inside the house?", "\"I think {D.he} said something like that. I could not hear every word because of the music.\""),
               .cross("Did you strike or force {DL} down?", "\"No, I did not. I took hold of an arm and let go when it was pulled away.\""),
               .cross("The neighbors were touchy, weren't they?", "\"Maybe, but three complaints in a month is not nothing, and the neighbors who called were polite and tired.\"")],
        theory: ("{D} walked away from a deputy and pulled free of the deputy's hand.", "{D} was a homeowner who walked into {D.his} own house and did not mean to resist."),
        allocution: "\"I should have talked to the deputies. It was my house, and I was embarrassed in front of my guests, and I walked back inside instead of giving my name. I pulled my arm back twice. I'm sorry for how I acted, and I'll keep the music down next time.\"",
        truths: ("{DL} had said, 'you can't touch me inside my house.'", "The deputy followed {D} into the house without a warrant, the video showed."),
        defendant: [.direct("Why did you walk away from the deputy?", "\"It was my own house, and I was embarrassed in front of my guests. I walked back inside instead of giving my name, and I wish I could take it back.\""),
               .direct("Did you pull your arm away from the deputy?", "\"Yes, I pulled my arm back twice. I did not think of it as resisting, because I was only trying to get inside my own door.\""),
               .direct("Why did you not give the deputy your name?", "\"I was upset, and I did not think I had to in my own front yard. I should have talked to the deputies like a grown person.\""),
               .direct("What did you say to the deputy as you walked away?", "\"I said something like you cannot touch me inside my house. I said it in anger, and I did not know the law on that.\""),
               .direct("How loud was the music that night?", "\"It was loud, I will admit. I did not think it was loud enough to bother anyone, but I know the neighbors do not agree.\""),
               .direct("What do you regret about that night?", "\"I should have turned the music down the first time and answered the deputy. I will keep it down next time, and I will give my name when I am asked.\""),
               .cross("You refused to give your name when the deputy asked, didn't you?", "\"Yes, I did, and I should not have. A name would have ended the whole thing in a minute.\""),
               .cross("You were before this court in {PRIORDATE} over {PRIOR}, weren't you?", "\"Yes, and I know I should have known better than to argue with a deputy. I had learned that lesson once already.\""),
               .cross("You pulled your arm away twice, didn't you?", "\"Yes, twice, and I know the camera shows it. I did not strike anyone or shove anyone.\""),
               .cross("This was the third noise call in a month at your address, wasn't it?", "\"Yes, though the neighbors are touchy and some of those calls were for ordinary music. I know that does not excuse the third one.\""),
               .cross("The deputy stayed on your front steps and did not enter the house, correct?", "\"I think so, though I do not remember exactly where the deputy stood. I was upset and I was looking at my guests.\"")],
        openings: ("Deputies were called a third time in a month to {D}'s address for loud music, and {D} refused to give a name and walked inside. The body camera shows {D} pulling away from the deputy's hand twice, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will present a homeowner who was embarrassed in front of guests and who walked into {D.his} own house. A deputy who follows without a warrant may be going beyond the law."),
        closings: ("Three noise calls in a month, a refusal to give a name, and an arm pulled away twice on a body camera. {D} had been here before.", "A homeowner at {D.his} own door, a deputy without a warrant, and two pulls of an arm that did no harm. The State has not shown that {D} meant to resist a lawful duty."),
        timeline: [(0, "Late night: deputies respond to the third noise complaint at {D}'s address in a month."), (0, "{D} refuses to give a name and walks toward the house."), (0, "The deputy follows and takes {D}'s arm, and {D} pulls away twice on the body camera."), (1, "{D} is charged with resisting a public officer.")],
        identified: "The deputy's body camera.",
        doctrines: ["searchSeizure", "burdenOfProof"],
        genders: ["D": .male])

    static let dirtBikeLawn = SmallCases.make(
        key: "story.followup.dirtBikeLawn",
        category: .property,
        headlines: ["Dirt Bike Tore Up Church Lawn", "Property Damage Charge After Dirt Bike Stunts"],
        law: "injuryRealProperty",
        spec: "Willfully and wantonly damaged real property of {V}, a church lawn and sign, causing damage of $1,300, on {DATE}.",
        ages: 18...30,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} rode a dirt bike across the lawn of {V}'s church, leaving deep ruts and snapping the church sign. {DL} says the bike's throttle stuck.",
        state: [E(.video, 3, "Church Camera", "A dirt bike circles the lawn three times and hits the sign."), E(.document, 2, "Repair Estimate", "$1,300 for sod and a new sign.")],
        defense: [E(.statement, 1, "Stuck Throttle", "{DL} says the throttle stuck open.")],
        role: "Sheriff's deputy",
        exam: [.direct("What is your assignment?", "\"I am a sheriff's deputy. I respond to property damage reports, and that evening I was sent to a church on the edge of town after the pastor called.\""),
               .direct("What did you find at the church?", "\"Deep ruts across the lawn in front of the building, torn sod, and the church's welcome sign snapped off at its base. The sign was lying on its side.\""),
               .direct("What does the church camera show?", "\"A dirt bike circling the lawn three times, tearing up the grass, and then hitting the sign. The rider's face is covered by a helmet.\""),
               .direct("How did you identify the rider?", "\"The bike's plate is registered to {DL}. I went to {D.his} address and found the bike in the garage with grass in the tires.\""),
               .direct("What did {DL} say?", "\"{D.He} said the throttle stuck open and {D.he} could not stop. {D.He} said it was an accident and that {D.he} was trying to stop when the bike hit the sign.\""),
               .direct("What was the damage?", "\"$1,300 for new sod and a new sign. The sign had been donated by a family in memory of their mother, and the church could not replace it from its budget.\""),
               .direct("What happened at the moment of impact?", "\"On the video, the engine noise stops when the bike hits the sign. That is when the rider falls off.\""),
               .cross("A stuck throttle can cause a bike to keep going, can it not?", "\"It can, yes. But a stuck throttle does not turn a bike in three tidy circles, and the video shows careful turns.\""),
               .cross("Was the throttle cable frayed?", "\"A mechanic later said it was frayed. I did not inspect it myself.\""),
               .cross("Did {DL} ride away after the crash?", "\"No, {D.he} stayed at the scene until the pastor came out. {D.He} apologized to the pastor.\""),
               .cross("Was anyone hurt?", "\"No one was seriously injured. {DL} had a scrape on the elbow from the fall, and I offered an ambulance, which {D.he} declined.\""),
               .cross("You cannot tell from the video what {DL} was feeling, can you?", "\"No, I cannot. I can tell you only what the bike did.\"")],
        theory: ("{D} rode a dirt bike in circles across a church lawn and broke the sign.", "{D}'s throttle stuck open and {D} could not stop the bike."),
        allocution: "\"I'll pay for the sign. The throttle stuck on that bike, and I was trying to stop and couldn't, and I ripped across the church lawn. I'm sorry for the ruts and for the damage to {V}'s church. I've been in this room before, and I'll fix everything I broke.\"",
        truths: ("{DL} told a friend, 'watch me cut up that grass.'", "The bike's throttle cable was frayed, a mechanic confirmed."),
        defendant: [.direct("What happened on the church lawn?", "\"The throttle stuck open on my bike, and I could not stop it. I was trying to turn it off and it kept going.\""),
               .direct("Why did you circle the lawn?", "\"I was trying to stop and could not. I was steering the only way I could to avoid the building and the parking lot.\""),
               .direct("Did you hit the sign on purpose?", "\"No, I hit it because I had no other choice. If I had not, I would have hit the church doors.\""),
               .direct("Did you tell anyone beforehand that you would ride there?", "\"I may have said something to a friend about cutting up grass. I was joking, and I did not mean the church.\""),
               .direct("What did you do when the bike stopped?", "\"I got up, checked that I was not hurt, and waited for the pastor to come out. I told the pastor I would pay for the sign.\""),
               .direct("What do you regret?", "\"I am sorry for the ruts and for the damage to the church. I will fix everything I broke.\""),
               .cross("You were doing stunts on that bike before, weren't you?", "\"I have ridden in fields, and that was different. This was not a stunt, because I could not stop.\""),
               .cross("You were here before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"Yes, and I know how that looks beside this. I would not cut up a church lawn on purpose.\""),
               .cross("You said watch me cut up that grass, didn't you?", "\"I said something like that to a friend, but I was talking about my own yard. I did not mean the church.\""),
               .cross("The bike circled three times, didn't it?", "\"Yes, and I know exactly how it looks to the court. I was trying to kill the engine and could not.\""),
               .cross("A frayed cable is a repair you should have made, shouldn't you?", "\"Yes, and I should have fixed it long before. I am sorry.\"")],
        openings: ("A church's camera shows a dirt bike circling its lawn three times, tearing up the sod, and snapping the sign. The bike is registered to {D}, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will present a throttle cable that a mechanic found frayed, and a rider who stayed at the scene and apologized to the pastor. A mechanical failure is not a willful injury to property."),
        closings: ("Three circles on a church lawn, a sign broken at its base, and $1,300 of ruts and sod to repair. A stuck throttle does not turn in neat circles, and {D} had been here before for damage like this.", "A frayed cable, a stuck throttle, and a rider who stayed and offered to pay. The State has not shown that {D} meant to damage anything."),
        timeline: [(0, "Evening: a dirt bike circles the church lawn three times and strikes the sign."), (0, "The pastor calls deputies and {D} waits at the scene."), (1, "A deputy finds the bike registered to {D} and the pastor shows deputies the video.")],
        identified: "The church's camera.",
        impact: "The sign was donated by a family in memory of their mother, and it was snapped in two when that dirt bike came across the lawn. The ruts are deep, and our volunteers spent two Saturdays repairing the grass. It hurt the family who gave it more than it hurt the church.")

    static let schoolWallPaint = SmallCases.make(
        key: "story.followup.schoolWallPaint",
        category: .property,
        headlines: ["School Wall Tagged Over Weekend", "Same Tag Appears on School Building"],
        law: "injuryRealProperty",
        spec: "Willfully and wantonly damaged real property of {V}, an elementary school wall, causing damage of $900, on {DATE}.",
        ages: 18...30,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, the same tag appeared on the wall of an elementary school. A custodian found {D} sleeping in a car in the lot with paint on {D.his} hands.",
        state: [E(.physical, 3, "Paint Cans", "Cans matching the tag, in {D}'s car.", .search), E(.video, 2, "School Camera", "A figure at the wall at 3 a.m.")],
        defense: [E(.statement, 1, "Passenger", "{DL} says a friend painted while {D.he} slept.")],
        role: "School custodian",
        exam: [.direct("What is your job at the school?", "\"I am the head custodian at an elementary school. I open the building before dawn, check the grounds, and clean up whatever happened overnight.\""),
               .direct("What did you find that morning?", "\"A fresh tag on the front wall of the school, and a car parked in the lot with someone asleep in it. I recognized the tag from a case in the news.\""),
               .direct("Who was in the car?", "\"{DL}, sleeping in the driver's seat with the seat tilted back. There were paint cans in the back seat.\""),
               .direct("What was on {DL}'s hands?", "\"Wet paint, the same color as the tag. It was on the fingers and the palms, and some had smeared on the steering wheel.\""),
               .direct("What did the school camera show?", "\"A figure at the wall around three in the morning, spraying. The face is covered, and the camera cannot tell who it is.\""),
               .direct("What did you do?", "\"I called the sheriff's office and kept an eye on the car until a deputy came. I did not wake {DL} up.\""),
               .direct("What did it cost the school?", "\"Hours of repainting, and a morning of explaining it to children who saw it. The school budget has no extra money for that.\""),
               .cross("Was {DL} awake when you found {D.him}?", "\"No, {D.he} was asleep when I first saw {D.him}, and {D.he} woke up only when I knocked on the window. {D.He} seemed groggy and surprised.\""),
               .cross("Was {DL} the person on the camera?", "\"I cannot say, because the figure had a hood up and the camera was set at a bad angle. I could not tell who it was.\""),
               .cross("Was there more than one person in the lot?", "\"I saw only {DL}, but there may have been others earlier in the night. I did not get there until six in the morning.\""),
               .cross("Does the tag match the one under the bridge?", "\"It looks like it to me, with the same lettering and the same color. I am not an expert, but it looked the same.\""),
               .cross("You did not see anyone paint, did you?", "\"No, I did not see anyone paint. I saw only the finished tag, the car in the lot, and the paint on {DL}'s hands.\"")],
        theory: ("{D} tagged an elementary school after being caught at an underpass.", "{D} handed paint cans to a friend and fell asleep in the car while the friend painted."),
        allocution: "\"I won't do it again. I handed cans to a friend that night, and I fell asleep in the car afterward. I'm sorry I was part of putting that tag on a school wall where little kids would see it. I'll help clean it up myself.\"",
        truths: ("{DL}'s signature tag matched both walls.", "The friend admitted painting and said {DL} stayed in the car."),
        defendant: [.direct("Did you paint that wall?", "\"No, I did not paint it. I was asleep in the car for most of the night, and I did not know anything about the wall until the custodian knocked.\""),
               .direct("Why was there wet paint on your hands?", "\"I handed cans to a friend that night, and some paint got on my fingers when I passed them over. I never sprayed anything myself.\""),
               .direct("Who is the friend who did the painting?", "\"A person I know who asked me to drive. I stayed in the car, fell asleep, and did not see where the friend went after that.\""),
               .direct("Why were the paint cans in your car?", "\"They were in the back seat. My friend and I had picked them up earlier that evening, and I did not think about what they would be used for.\""),
               .direct("Is the tag on the wall yours?", "\"A lot of people use that tag, and it is not mine alone. I have seen it in many places around town.\""),
               .direct("What do you regret about that night?", "\"I am sorry I was part of putting a tag on a school wall where little kids would see it. I will help clean it up myself.\""),
               .cross("You handed paint cans to a friend, didn't you?", "\"Yes, I did, and I should not have. I thought it was a joke that would not reach a school, and I was wrong.\""),
               .cross("You were before this court in {PRIORDATE} over {PRIOR}, weren't you?", "\"Yes, and I know that makes this look bad. I was trying to stay out of it by staying in the car.\""),
               .cross("The same tag was at the underpass in your earlier case, wasn't it?", "\"It is a common tag that many people use. I cannot say who else was involved in that one either.\""),
               .cross("You had wet paint on your hands when the custodian found you, didn't you?", "\"Yes, from handing the cans over. It did not come from spraying a wall.\""),
               .cross("You fell asleep in the driver's seat, didn't you?", "\"Yes, because I was tired, and I should have driven home. I did not think about where I was parked.\"")],
        openings: ("At three in the morning a hooded figure painted a tag on the front wall of an elementary school, and at six the custodian found {D} asleep in a car in the lot with wet paint on {D.his} hands. {DL} came before this court in {PRIORDATE} over {PRIOR}, and the cans in the back seat match the tag.", "The defense will present a friend who admitted painting and a passenger who stayed in the car. Handing someone a can is wrong, but it is not the same as painting."),
        closings: ("The same tag as the underpass, cans matching it in {D}'s car, and wet paint on {D}'s hands at six in the morning. {D} had been before this court for it.", "A friend who admitted painting, a passenger who fell asleep, and a tag that many people use. The State has not shown that {D} was the one at the wall."),
        timeline: [(0, "3 a.m.: a figure paints a tag on the front wall of the elementary school."), (0, "6 a.m.: the custodian finds {D} asleep in a car in the lot with wet paint on {D.his} hands."), (0, "A deputy searches the car and finds paint cans matching the tag.")],
        identified: "The custodian's discovery.",
        impact: "Children saw it before the custodian could cover it. The tag was on the front wall of our elementary school, and kids asked their teachers what it meant on the way in. We spent the morning explaining it. It took hours to repaint, and the school budget has no extra money for that.",
        genders: ["D": .male])

    static let falseAlarmTwo = SmallCases.make(
        key: "story.followup.falseAlarmTwo",
        category: .publicOrder,
        headlines: ["Another False Fire Call, Another Prepaid Phone", "Second False Report for Man in Earlier Case"],
        law: "falseReport",
        spec: "Willfully made a false report to law enforcement that a vehicle was on fire, on {DATE}.",
        ages: 19...50,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, another call reported a car on fire in front of {D}'s ex-wife's new home. Again the caller used a prepaid phone. This time a gas station camera showed {DL} buying it with cash.",
        state: [E(.video, 3, "Gas Station Camera", "{D} buys a prepaid phone with cash."), E(.digital, 2, "911 Recording", "A man says a car is on fire.")],
        defense: [E(.statement, 1, "Gift", "{DL} says {D.he} bought the phone for a friend.")],
        role: "Sheriff's detective",
        exam: [.direct("What is your assignment with the sheriff's office?", "\"I am a detective. I work false reports, harassment, and cases where a phone is used to make trouble for another person.\""),
               .direct("What was reported on this call?", "\"A caller told 911 that a car was on fire in front of a home. The address was the new home of {DL}'s ex-wife, and two fire crews were sent.\""),
               .direct("What did the crews find?", "\"No fire and no burning car. The car in the driveway was parked and cool, and the neighbors had not smelled any smoke at all.\""),
               .direct("What did the 911 recording show?", "\"A man's voice saying that a car was on fire and giving the address twice. The call lasted less than a minute and came from a prepaid phone.\""),
               .direct("How did you tie that phone to {DL}?", "\"A gas station camera shows {DL} buying a prepaid phone with cash the day before. The serial number on the box matches the phone that placed the call.\""),
               .direct("Was this the first call of its kind to that address?", "\"No. An earlier false call was made to the same address from another prepaid phone, and that was the subject of the earlier case in this court.\""),
               .direct("What did {DL} tell you when you asked about the phone?", "\"{D.He} said {D.he} bought it as a gift for a friend and never used it to make a call. {D.He} gave me a first name for the friend.\""),
               .cross("The voice on the recording has not been identified, has it?", "\"No. Nobody has matched that voice to {DL}, and I would not tell the jury that I can.\""),
               .cross("Is there any record of {DL} using that phone?", "\"I have no record of {DL} using it. The only activity on the phone is the call to 911.\""),
               .cross("Could someone else have used {DL}'s money to buy it?", "\"The camera shows {DL} paying in cash and walking out with the box. It is possible that the phone changed hands later, though I have no proof of that.\""),
               .cross("Did you find the friend {DL} named?", "\"I looked for a person by that name and could not find anyone. That does not mean the person does not exist.\""),
               .cross("You cannot say who actually spoke on that call, can you?", "\"That is correct, I cannot say who spoke. I can say only who bought the phone and when.\"")],
        theory: ("{D} made a second false fire report to a former spouse's address from a new prepaid phone.", "{D} bought a phone as a gift for a friend and never made the call."),
        allocution: "\"I bought that prepaid phone with cash at the gas station for a friend, and I never used it to make a call about a fire. I'm sorry for the trouble to the fire crews.\"",
        truths: ("{DL}'s friend didn't exist.", "{DL}'s brother bought the phone and used it."),
        defendant: [.direct("Did you call 911 about a fire at your ex-wife's home?", "\"No, I did not make that call. I never used that phone for a call about a fire, and I never used it for anything.\""),
               .direct("Why did you buy a prepaid phone?", "\"I bought it as a gift for a friend who asked me to pick one up on my way home. The friend said the friend's own phone had been lost.\""),
               .direct("Who is that friend?", "\"A friend from work whom I know by a first name. I have been trying to reach that person since the deputies came, and I cannot.\""),
               .direct("Why did you pay with cash?", "\"I always pay with cash for small purchases. I did not think about how it might look, and I did not know anyone was watching me.\""),
               .direct("Did you know about the earlier call to that address?", "\"I knew about it from the earlier case. I did not think about it when I bought the phone, because the two things had nothing to do with each other in my mind.\""),
               .direct("What do you regret about all of this?", "\"I am sorry for the trouble to the fire crews who rushed out. I should have been more careful about whose hands that phone went into.\""),
               .cross("You bought the phone with cash on camera the day before the call, didn't you?", "\"Yes, I did, for a friend. I know the timing is bad, and I have said so from the first day.\""),
               .cross("You were here before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"Yes, and I know how this looks to the jury. I have learned my lesson about that address, and I stay away from it.\""),
               .cross("Your friend cannot be found, can your friend?", "\"I have not been able to reach my friend since the deputies called me. I have given the detective everything I know.\""),
               .cross("The call was about your ex-wife's new home, wasn't it?", "\"Yes, that is what the detective told me. I did not know where my ex-wife had moved until the earlier case.\""),
               .cross("You were angry with your ex-wife about the move, weren't you?", "\"I was upset about some things, but I would never use a fire call to get back at anyone. I am past that.\"")],
        openings: ("A 911 caller reported a car on fire in front of the new home of {D}'s ex-wife, and crews found no fire. The call came from a prepaid phone that {D} bought with cash the day before, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will present a phone bought as a gift for a friend and a voice on the recording that no one has matched. A purchase at a gas station is not a call to 911."),
        closings: ("A prepaid phone bought with cash by {D}, a call to the ex-wife's address, and the same pattern as the earlier case. {D} had been before this court on that very charge.", "A voice no one has identified and a friend who is hard to find. The State has not shown who spoke on that call, only who bought the phone."),
        timeline: [(-1, "{D} buys a prepaid phone with cash at a gas station and a camera records it."), (0, "A caller uses that phone to report a car on fire in front of {D}'s ex-wife's new home."), (0, "Fire crews find no fire."), (1, "A detective traces the phone's serial number to {D}'s purchase.")],
        identified: "The store camera.",
        genders: ["D": .male])

    static let badgeObstruction = SmallCases.make(
        key: "story.followup.badgeObstruction",
        category: .publicOrder,
        headlines: ["Man Told Deputy He Was an Officer, Charged Again", "Obstruction Charge After Second Badge Incident"],
        law: "obstruction",
        spec: "Willfully and unlawfully delayed and obstructed a public officer by claiming to be an officer, on {DATE}.",
        ages: 22...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} told a deputy at a traffic stop that {D.he} was an off-duty officer and asked to be let go. A call to the sheriff's office confirmed {DL} was not an employee.",
        state: [E(.video, 3, "Body Camera", "{D} says, 'I'm with the sheriff's office, give me a break.'"), E(.document, 2, "Personnel Check", "No record of employment with any agency.")],
        defense: [E(.statement, 1, "Joke", "{DL} says {D.he} was making a joke.")],
        role: "Sheriff's deputy",
        exam: [.direct("What is your assignment with the sheriff's office?", "\"I am a patrol deputy on the evening shift. I make traffic stops, answer calls, and write reports, and I have worked this district for six years.\""),
               .direct("Why did you stop {DL}?", "\"A taillight was out on the car, and I pulled in behind it on a county road. It was a routine stop, and nothing else about the car looked unusual.\""),
               .direct("What did {DL} say when you got to the window?", "\"{D.He} told me, I'm with the sheriff's office, give me a break. {D.He} said it plainly, and then {D.he} asked me to let {D.him} go.\""),
               .direct("What does your body camera show?", "\"It shows the stop from the time I step out of the cruiser. You can hear the words clearly, and you can see {DL} reach for a wallet.\""),
               .direct("What did you do when you heard that?", "\"I asked which unit {D.he} worked with, and {D.he} could not give me a name. I called the sheriff's office on the radio to check.\""),
               .direct("What did the personnel check show?", "\"No record of employment with any agency in the county. {DL} had not worked for the sheriff's office, and there was no off-duty status.\""),
               .direct("How did {DL} react when you told {D.him}?", "\"{D.He} said it was a joke. I told {D.him} I did not find it funny, and I wrote a citation for the taillight and a report for the false claim.\""),
               .cross("It was a joke, wasn't it?", "\"That is what {D.he} told me afterward. I was not laughing, and I took it seriously because a false claim to an officer can cause real problems.\""),
               .cross("Did {DL} offer a badge or an ID as proof?", "\"No, {D.he} did not show me anything. I did not see a badge, and I did not see a card.\""),
               .cross("Did {DL} threaten you or argue after you checked?", "\"No, {D.he} was polite and apologetic. {D.He} said sorry and said {D.he} meant nothing by it.\""),
               .cross("Did {DL} have a coworker who was a deputy?", "\"I have heard that, and I have not checked. I did not ask about {D.his} coworkers.\""),
               .cross("You cannot say what {DL} intended, can you?", "\"No, I cannot say what {D.he} had in mind. I can tell you what {D.he} said and what happened next.\"")],
        theory: ("{D} claimed to be an off-duty officer to talk {D.his} way out of a traffic stop.", "{D} made a poor joke at a traffic stop and never meant to be let go."),
        allocution: "\"It was stupid. I told that deputy I was an off-duty officer as a joke at a traffic stop, and I never meant to be let go because of it. I know it wasn't funny to him. I've been in this courtroom before, and I'm sorry for wasting his time and the court's.\"",
        truths: ("{DL}'s phone held the photo of the badge.", "{DL} had a coworker who was a deputy and had joked about it."),
        defendant: [.direct("Why did you tell the deputy you were with the sheriff's office?", "\"It was a stupid joke. I was nervous and tried to be funny, and the words came out of my mouth before I thought.\""),
               .direct("Did you want to avoid a ticket?", "\"No, I did not. I knew I had a taillight out, and I expected a ticket. The joke was not an attempt to be let go.\""),
               .direct("Where did you get the idea?", "\"I have a coworker who is a deputy and who jokes about it. I have joked about it too, and I did not think about doing it in front of a real deputy.\""),
               .direct("What was on your phone?", "\"A photo of a badge that my coworker sent me as a joke. I did not show it to the deputy, and I never carried a real one.\""),
               .direct("How did you feel when the deputy called the sheriff's office?", "\"Ashamed. I knew right away that I had made a mistake, and I tried to say so.\""),
               .direct("What do you regret?", "\"I am sorry for wasting the deputy's time and the court's time. It was not funny, and I will never do it again.\""),
               .cross("You told a deputy you were an officer, didn't you?", "\"Yes, I did, and I know how serious that is. I should never have said it, even as a joke.\""),
               .cross("You asked to be let go, didn't you?", "\"I said give me a break, and I meant it as a joke. I did not expect the deputy to let me go.\""),
               .cross("You were before this court in {PRIORDATE} over {PRIOR}, weren't you?", "\"Yes, and I know that makes the joke look worse. I was trying to be funny, not to fool anyone.\""),
               .cross("Your phone had a photo of a badge, didn't it?", "\"Yes, a photo my coworker sent me as a joke. I never used it for anything.\""),
               .cross("You did not tell the deputy you were joking until after the call, did you?", "\"No, I did not, and I should have said it sooner. I was too embarrassed to speak.\"")],
        openings: ("At a traffic stop for a taillight, {D} told the deputy, I'm with the sheriff's office, give me a break, and asked to be let go. The body camera records it, no agency employs {D}, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will present a joke made by a nervous driver who expected a ticket. A false claim made in jest, with no badge shown, is a poor decision but not an obstruction."),
        closings: ("A false claim to a deputy, caught clearly on a body camera, and a request to be let go. {D} had been here before for a similar claim.", "A nervous joke, a coworker who is a deputy, and a photo that never left a phone. The State has not shown that {D} meant to hinder anyone, only to be funny."),
        timeline: [(0, "Evening: a deputy stops {D} for a taillight."), (0, "{D} tells the deputy {D.he} is with the sheriff's office and asks for a break, on the body camera."), (0, "The deputy calls the sheriff's office and learns that no agency employs {D}."), (1, "The deputy writes a citation and a report and {D} is charged.")],
        identified: "The deputy's body camera.",
        genders: ["D": .male])

    static let pistolInTruck = SmallCases.make(
        key: "story.followup.pistolInTruck",
        category: .publicOrder,
        headlines: ["Loaded Pistol Found Under Truck Seat", "Concealed Weapon Charge After Fair Case"],
        law: "concealedWeapon",
        spec: "Carried a concealed handgun in a vehicle without a permit, on {DATE}.",
        ages: 24...66,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} was stopped for a taillight and a deputy found a loaded pistol under the truck seat. {DL} says {D.he} had applied for a permit and it was pending.",
        state: [E(.physical, 3, "The Pistol", "A loaded pistol under the driver's seat.", .search), E(.document, 2, "Permit Check", "No permit on file.")],
        defense: [E(.document, 2, "Application", "A permit application filed two weeks earlier.")],
        role: "Sheriff's deputy",
        exam: [.direct("What led you to stop {DL}'s truck that evening?", "\"A taillight was out on the passenger side, so I pulled the truck over on the county road and asked for a license and registration.\""), .direct("What did you find during the stop?", "\"After I asked {DL} to step out, I looked in the cab and found a loaded pistol under the driver's seat, within easy reach of where {D.he} had been sitting.\""), .direct("How did you know the pistol was loaded?", "\"I cleared it at the scene. There was a magazine seated and a round in the chamber, and I secured it before I did anything else.\""), .direct("What did you check about a permit?", "\"I ran the name through the sheriff's records and the state database, and neither showed a concealed handgun permit on file for {D.him}.\""), .direct("What did {DL} say about a permit?", "\"{D.He} told me {D.he} had applied for one about two weeks earlier and that the application was still pending.\""), .direct("What did you do with the pistol?", "\"I photographed where it was found, logged it, and sent it to the property room with the permit check attached to my report.\""), .cross("You stopped the truck only because of a taillight, correct?", "\"Yes. That was the only reason for the stop, and nothing else about the truck or the driving drew my attention.\""), .cross("{DL} was calm and cooperative with you?", "\"{D.He} answered every question and gave me no trouble at any point during the stop.\""), .cross("You later saw proof that an application had been filed?", "\"I saw a copy of the receipt afterward, but a pending application isn't a permit, and nothing on file covered {D.him} that night.\""), .cross("The pistol was under the seat, not in {D.his} hand or waistband?", "\"That's correct. It was under the driver's seat, and I never saw {D.him} reach for it.\""), .cross("{DL} didn't try to hide it or deny it?", "\"No. When I told {D.him} what I had found, {D.he} didn't argue and said {D.he} had meant to wait on the permit.\"")],
        theory: ("{D} carried a loaded pistol in a truck with no permit.", "A pending permit application showed good faith, not a plan to break the law."),
        allocution: "\"I'll wait for the permit. I applied for it, and I carried that pistol under the seat for safety, thinking the paperwork was close enough. I was wrong. I'm sorry for the danger, and I've been in this courtroom before and will not carry again until I'm cleared.\"",
        truths: ("No permit was on file, and the pistol was loaded and within reach.", "The application was real and had been filed two weeks before the stop."),
        defendant: [.direct("Why were you carrying a pistol in the truck?", "\"I drive a lot of back roads at night for work, and I wanted something for protection after a break-in at my shop last winter.\""), .direct("Did you have a permit that night?", "\"No. I had applied two weeks earlier and was told it could take a month or more, but I didn't have the permit in my hand.\""), .direct("Why did you keep the pistol under the seat?", "\"I didn't want it in plain sight, and I figured under the seat was safer than a glove box that anybody could open.\""), .direct("What did you understand about the application?", "\"I thought filing the paperwork meant I was almost cleared, and I took that to mean the permit was close enough. I was wrong about that.\""), .direct("What happened when the deputy found it?", "\"I told the deputy the truth and handed over the application receipt. I didn't argue and I never moved toward the seat.\""), .direct("Why did you have it with you that night in particular?", "\"I was driving home late from a job across the county, and I didn't want to leave it in an empty shop overnight.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, I had, and I knew how seriously the court takes weapons. That's why I filed the application instead of ignoring the rule.\""), .cross("You knew you needed a permit before carrying it?", "\"I did, which is exactly why I applied. I just misjudged how long I had to wait before it was safe to carry.\""), .cross("A pending application doesn't authorize anything, does it?", "\"No, I understand that now. At the time I wasn't thinking about the difference between applying and being approved.\""), .cross("You kept a loaded pistol within reach on a public road?", "\"Yes. It was loaded and under the seat, and I accept that it was a risk I shouldn't have taken.\""), .cross("You never called the sheriff's office to ask whether you could carry it?", "\"No. I should have called and asked, and I didn't. I assumed the paperwork was enough.\"")],
        openings: ("A deputy stopped a pickup for a taillight and found a loaded pistol under the driver's seat. {D} had no concealed handgun permit on file, and {D.he} has stood in this courtroom before. The State will show a loaded weapon within reach and no permit.", "{D} had filed an application for a permit two weeks earlier and meant to follow the rules. {D.He} was cooperative, never reached for the weapon, and misjudged how long the paperwork would take. The defense asks the court to weigh that."),
        closings: ("A loaded pistol sat under the seat of a truck on a public road, and the records show no permit that night. A pending application is not a permit. {D} knew the rule and carried the weapon anyway.", "{D} applied, told the deputy the truth, and never touched the weapon. This is a misjudged deadline, not a plan to hurt anyone, and the court may take that into account."),
        timeline: [(0, "Evening: a deputy stops the truck for a taillight."), (0, "The deputy finds a loaded pistol under the driver's seat."), (0, "A records check shows no permit on file."), (1, "{DL} is charged with carrying a concealed weapon.")],
        identified: "A deputy found the pistol during a taillight stop.",
        genders: ["D": .male])

    static let secondDogChained = SmallCases.make(
        key: "story.followup.secondDogChained",
        category: .publicOrder,
        headlines: ["Second Dog Found Chained Without Water", "Animal Control Cites Owner Again"],
        law: "animalCruelty",
        spec: "Intentionally deprived an animal, a dog, of necessary sustenance, on {DATE}.",
        ages: 22...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, animal control found a second dog chained in the same yard in 95-degree heat with an empty bowl. {D} says the first dog died of old age and this dog is a puppy.",
        state: [E(.physical, 3, "The Bowl", "An empty bowl, a chain to a post, no shade.", .search), E(.document, 2, "Veterinary Report", "Dehydration in a puppy.")],
        defense: [E(.statement, 1, "New Puppy", "{DL} says the puppy was a gift two days earlier.")],
        role: "Animal control officer",
        exam: [.direct("What brought you to the yard that afternoon?", "\"We got a call about a dog left chained outside in the heat, and I arrived to find the temperature near ninety-five degrees.\""), .direct("What did you find in the yard?", "\"A puppy was chained to a post with no shade, and the only bowl in reach was completely empty and dry.\""), .direct("What was the dog's condition?", "\"It was panting hard, lethargic, and slow to respond. I moved it into the shade and gave it water right away.\""), .direct("What did the veterinarian determine?", "\"The vet's report found dehydration in a young dog and said it would not have lasted much longer in that heat.\""), .direct("Why did this yard matter to you?", "\"Animal control had been to the same yard before on another dog, so I knew the address and who lived there.\""), .direct("What did {DL} say to you?", "\"{D.He} told me the dog was a new puppy and that the earlier dog had died of old age.\""), .cross("The dog was a different dog from the earlier case, wasn't it?", "\"Yes, it was a different animal, but it was the same yard and the same arrangement with a chain and a post.\""), .cross("The puppy had only been there two days?", "\"That's what {DL} told me, and I had no records to dispute it.\""), .cross("You did find a bowl in the yard?", "\"Yes, but it was empty and dry, and there was no other water within the puppy's reach.\""), .cross("The puppy recovered?", "\"It did, after treatment, and it was released to a rescue group and is doing well.\""), .cross("{DL} cooperated with you?", "\"{D.He} was polite and let me take the dog, and I did not have any trouble from {D.him}.\"")],
        theory: ("{D} left a second dog chained in the heat without water.", "The puppy was new, and the lack of water was carelessness, not cruelty."),
        allocution: "\"No more dogs. I chained that puppy in the morning to keep it from running, and I didn't think about the heat or the bowl. I've been in this courtroom before about another animal. I'm sorry for the suffering, and I'll never keep an animal again.\"",
        truths: ("The bowl was empty, the puppy was dehydrated, and there was no shade.", "The puppy was a gift two days earlier and the bowl had been filled that morning."),
        defendant: [.direct("How did you come to have the puppy?", "\"A friend gave it to me two days before. I had it in the yard in the mornings while I was getting it used to being outside.\""), .direct("Why was the puppy on a chain?", "\"It kept slipping the fence and heading for the road, and I chained it while I went in to work on the truck.\""), .direct("Did the puppy have water that day?", "\"I filled the bowl in the morning, but I didn't think about it tipping over or running dry as the day got hotter.\""), .direct("Did you know how hot it was?", "\"I knew it was a warm day, but I was working and didn't stop to think about how hot it was getting out in the yard.\""), .direct("What happened to your earlier dog?", "\"That dog was old and died of natural causes. I never meant to treat any animal the way that case suggested.\""), .direct("What did you do when animal control arrived?", "\"I told the officer exactly what I'd told you, and I let the officer take the puppy without any argument.\""), .cross("You had been in this courtroom before over an animal, hadn't you?", "\"Yes, I had, and I knew better than to leave an animal outside without checking on it.\""), .cross("You left a puppy on a chain in ninety-five degree heat?", "\"Yes, and I should have brought it inside or at least into the shade. I didn't think it through.\""), .cross("The bowl was empty when the officer arrived?", "\"It was, and I don't know how long it had been empty. I should have checked on it.\""), .cross("A puppy that young can't get away from heat on its own, can it?", "\"No, it can't, and that's exactly why it was my job to make sure it was safe.\""), .cross("You didn't check on it for hours?", "\"No, I didn't, and I'm sorry for that. I lost track of time working on the truck.\"")],
        openings: ("Animal control found a puppy chained to a post in ninety-five degree heat with an empty bowl and no shade. The yard is the same one where officers came before, and {D} has been before this court. The State will show a dehydrated animal left without water.", "The puppy was a gift two days earlier, and the bowl was filled that morning. {D} lost track of time on a hot day, and nothing here shows an intent to hurt the animal. The defense asks the court to see carelessness, not cruelty."),
        closings: ("An empty bowl, a chain, and no shade in ninety-five degrees add up to a dehydrated puppy. The vet confirmed it. {D} has been here before over an animal and should have known better.", "{D} owned the puppy for two days and filled its bowl that morning. The failure was forgetting, not cruelty, and the animal recovered fully. The defense asks the court to weigh that."),
        timeline: [(0, "Morning: the puppy is chained and its bowl is filled."), (0, "Afternoon: animal control arrives in ninety-five degree heat."), (0, "The puppy is treated for dehydration."), (1, "{DL} is charged with cruelty to an animal.")],
        identified: "Animal control found the puppy chained without water.",
        mood: .wantsConviction)

    static let bumperAgain = SmallCases.make(
        key: "story.followup.bumperAgain",
        category: .traffic,
        headlines: ["Driver Hit Parked Truck, Left a Note With No Name", "Second Hit-and-Run for Same Driver"],
        law: "hitAndRunProperty",
        spec: "As the driver of a vehicle involved in a crash with an unattended vehicle, failed to give identifying information, on {DATE}.",
        ages: 19...70,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} scraped a parked truck belonging to {V}. {DL} left a note that said 'Sorry' with no name or number.",
        state: [E(.physical, 3, "The Note", "A note under the wiper that says only 'Sorry.'"), E(.video, 2, "Street Camera", "{D}'s car scraping the truck and stopping briefly.")],
        defense: [E(.statement, 1, "Note", "{DL} says {D.he} thought the note was enough.")],
        role: "Police officer",
        exam: [.direct("What were you called to that morning?", "\"I was called to a parking spot on a residential street where {V} found the side of a parked truck scraped and a note left under the wiper.\""), .direct("What did the note say?", "\"It said only the word 'Sorry.' There was no name, no phone number, and nothing that would have let the owner contact whoever had done it.\""), .direct("How did you identify the driver?", "\"A street camera caught a car scraping the truck and stopping briefly, and the plate on that car came back registered to {DL}.\""), .direct("What did the video show about the stop?", "\"The car pulled up to the truck, scraped it, paused for a few seconds, and then drove away without anyone getting out.\""), .direct("What damage did you document?", "\"I photographed a long scrape and a dented panel along the truck's rear quarter, and the paint transfer matched the color of {DL}'s car.\""), .direct("Did you speak with {DL}?", "\"Yes. I went to the address on the registration, and {D.he} admitted leaving the note and said {D.he} thought that was enough.\""), .cross("The note did say sorry, didn't it?", "\"It did, but it gave the owner nothing to use. The law requires a name and contact information, and the note had neither.\""), .cross("The car stopped briefly after the scrape?", "\"It did, for a few seconds, and then it left. Nobody got out to look at the truck or wait for the owner.\""), .cross("{DL} was polite when you spoke with {D.him}?", "\"Yes, {D.he} was polite and cooperative, and I had no trouble at the door when I asked about the truck.\""), .cross("The damage was to an unattended vehicle?", "\"Yes, the truck was parked and empty, which is why the note mattered so much for the owner to be found.\""), .cross("You can't say what {DL} was thinking when {D.he} left?", "\"No, I can only tell you what the camera showed and what {D.he} told me afterward about the note.\"")],
        theory: ("{D} left no name or number for the owner.", "A driver who thought a note was enough."),
        allocution: "\"I'll leave my number next time. I was late for work, and I scraped that truck and left a note that said 'Sorry' because I thought it was enough. I know now it wasn't. I'm sorry to {V}, and I'll pay for the repair.\"",
        truths: ("{DL}'s earlier case had spelled out the law.", "{DL} had no pen and left what {D.he} could."),
        defendant: [.direct("Why did you leave only the word 'Sorry'?", "\"I was late for work and in a hurry, and I wrote the first word that came to mind and put it under the wiper.\""), .direct("Did you know what the law required?", "\"I knew I should leave something, but I didn't think it through. I thought a note showed I wasn't running away from the mistake.\""), .direct("What happened when you hit the truck?", "\"I misjudged the turn on a narrow street and scraped the side. I stopped for a moment, then panicked about being late.\""), .direct("What did you do when the deputy came to your door?", "\"I told the deputy the truth right away and admitted it was my car. I didn't try to hide anything or blame someone else.\""), .direct("How do you feel about what happened to the owner?", "\"I feel bad for the owner. I should have left my number, and I should have stayed to talk to {V.him}.\""), .direct("What would you do differently?", "\"I would stop, wait if I had to, and leave my name and number so the owner could reach me without calling the police.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, I had. I knew how important it was to handle things properly, and I still made the wrong choice that morning.\""), .cross("You left without giving your name or number?", "\"Yes, that's true. I left only a note that said sorry, and I know it wasn't what the law required.\""), .cross("You were late for work, so you drove off?", "\"Yes. I let being late come ahead of doing the right thing for the owner, and I regret that.\""), .cross("A note without a name can't help an owner file a claim, can it?", "\"No, it can't. The owner had to call the police and wait for the camera to find me.\""), .cross("You have offered to pay for the damage now?", "\"I have, and I will pay the repair bill in full if the owner will let me.\"")],
        openings: ("After {DL}'s case in this court over {PRIOR}, {D} scraped a parked truck belonging to {V} and left only a note under the wiper that said 'Sorry.' The note had no name and no phone number, and the street camera shows the whole thing.", "{D} did not drive off in secret; {D.he} stopped, wrote a note, and left it where the owner would see it. The defense will say {D.he} honestly believed that was enough, and that a hurried apology is not an attempt to hide."),
        closings: ("A note that says 'Sorry' with no name or number gives the owner nothing to act on. The camera shows {D}'s car scrape the truck and stop, and {DL} knew from the earlier case what the law requires of a driver.", "{D} stopped, left a note, and did not run. That is the conduct of a driver who thought a written apology was enough, not of one trying to hide, and the State must prove otherwise beyond a reasonable doubt."),
        timeline: [(0, "Morning: the scrape."), (0, "{V} finds the note.")],
        identified: "The street camera and plate.",
        impact: "The note told me nothing, and my deductible was five hundred dollars. I came out to a scraped truck and a piece of paper with a single word on it. I had to take a day off work to deal with the insurance. I just wish the person had stood there and talked to me.",
        genders: ["D": .male])

    static let badCheckHardware = SmallCases.make(
        key: "story.followup.badCheckHardware",
        category: .whiteCollar,
        headlines: ["Second Bad Check, This Time at Hardware Store", "Closed Account Check Again"],
        law: "uttering",
        spec: "Uttered a check for $212 drawn on an account {D} knew was closed, on {DATE}.",
        ages: 28...66,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} wrote a $212 check to a hardware store on the same closed account. {DL} says {D.he} meant to open a new account and mixed up the checkbooks.",
        state: [E(.document, 3, "Returned Check", "Marked 'account closed.'"), E(.document, 2, "Bank Letter", "The account was closed before the earlier case.")],
        defense: [E(.statement, 1, "Checkbooks", "{DL} says {D.he} kept two checkbooks and used the wrong one.")],
        role: "Hardware store manager",
        exam: [.direct("How did you come to receive this check?", "\"A customer handed it to me at the counter for a purchase of two hundred twelve dollars of plumbing and electrical supplies.\""), .direct("What happened when the store deposited it?", "\"The bank returned it a few days later marked 'account closed,' and we had no way to collect from that account.\""), .direct("Did you know the customer?", "\"Yes. {DL} is a regular and has shopped at our store for years, so I accepted the check without a second thought.\""), .direct("What did you do when it came back?", "\"I called the number on file and left a message, and when I heard nothing I contacted the sheriff's office.\""), .direct("What did the bank tell you about the account?", "\"The bank's letter said the account had been closed before the day {DL} wrote the check, so it was closed when the check was written.\""), .direct("Was the store ever paid?", "\"Not until a deputy contacted {D.him}. Only then did {D.he} come in and cover what was owed.\""), .cross("{DL} has been a good customer for years, hasn't {D.he}?", "\"Yes, for years. That's why I took the check, and why it surprised me when it came back.\""), .cross("You had never had a problem with {D.him} before?", "\"Not that I recall. {D.He} always paid for what {D.he} bought in the past.\""), .cross("The check was for a legitimate purchase?", "\"Yes, the items were real and {D.he} took them with {D.him} that day.\""), .cross("{DL} paid you in full afterward?", "\"Yes, once the deputy called, {D.he} came in and paid the full two hundred twelve dollars.\""), .cross("You can't say whether {D.he} knew the account was closed?", "\"I can only say what the bank's letter says. I can't say what was in {D.his} mind when the check was written.\"")],
        theory: ("{D} wrote a check on the same closed account after the earlier case.", "A man with two checkbooks."),
        allocution: "\"I'll pay with cash from now on. I forgot that account was closed, and the checkbook was in the truck, and I mixed up the books. I never meant to write a bad check to a hardware store I use every week. I'm sorry, and I'll make that two hundred twelve dollars good today.\"",
        truths: ("{DL} had been told the account was closed.", "{DL} had just moved and put the new checkbook in a box."),
        defendant: [.direct("Why did you write a check on that account?", "\"I had two checkbooks, an old one and a new one, and I grabbed the old one out of the truck without looking.\""), .direct("Did you know the old account was closed?", "\"I knew I had closed it, but I forgot the old checkbook was still in the truck. I never meant to write a bad check.\""), .direct("What did you intend to do?", "\"I meant to open a new account and use only that checkbook, and I mixed up the books on the day I shopped.\""), .direct("What happened when you heard about the returned check?", "\"I was embarrassed, and I went to the store right away, apologized to the manager, and paid the whole amount.\""), .direct("Do you shop at that store often?", "\"Yes, every week. I would never want to cheat a store I use that often and where people know me.\""), .direct("What have you changed since then?", "\"I threw out the old checkbook and now pay with cash or a debit card so this can't happen again.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I knew better than to be careless with money matters. That's what makes me so ashamed of this one.\""), .cross("You wrote a check on a closed account?", "\"Yes, I did, but it was a mistake. I mixed up the checkbooks and didn't check which one I grabbed.\""), .cross("You didn't pay until a deputy called?", "\"That's right. I was embarrassed and slow to deal with it, and I should have gone in myself right away.\""), .cross("You knew you had closed that account?", "\"I did, but I had forgotten about the old checkbook. I closed it and never thought about it again.\""), .cross("You've repaid the store in full?", "\"Yes, all two hundred twelve dollars, plus an apology to the manager for the trouble it caused.\"")],
        openings: ("{D} wrote a $212 check to a hardware store drawn on an account that was already closed, and the bank returned it. {DL} came before this court in {PRIORDATE} over {PRIOR}, and the bank letter shows the account was closed before that earlier case even began.", "The defense will present a man who kept two checkbooks and reached for the wrong one. {D} meant to open a new account, mixed the books up, and had no intention of cheating the hardware store out of its supplies."),
        closings: ("A closed account does not honor checks, and {D} had already been through this court once over a bad check. The returned check, stamped 'account closed,' and the bank's letter show {D} knew or should have known better.", "Two checkbooks and one honest mix-up are all the evidence shows. {D} did not hide the account's status or flee the store, and a careless mistake with a checkbook is not the intent the State must prove."),
        timeline: [(0, "Afternoon: the check is written."), (10, "The store turns it over to deputies.")],
        identified: "The store's complaint.",
        genders: ["D": .male])

    static let threatByText = SmallCases.make(
        key: "story.followup.threatByText",
        category: .publicOrder,
        headlines: ["Text Threat Follows Facebook Post Case", "Neighbor Says Text Said 'You'll Be Sorry'"],
        law: "communicatingThreats",
        spec: "Willfully threatened to physically injure {V}, in a manner a reasonable person would believe would be carried out, on {DATE}.",
        ages: 24...62,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} texted {V}: 'You'll be sorry you called the sheriff.' {V} kept the message and called deputies.",
        state: [E(.digital, 3, "Text Message", "'You'll be sorry you called the sheriff.'"), E(.document, 2, "Phone Record", "The text came from {D}'s number at 9:40 p.m.")],
        defense: [E(.statement, 1, "Sorry", "{DL} says it meant {V} would regret the trouble, not a threat.")],
        role: "Sheriff's deputy",
        exam: [.direct("What were you called to that night?", "\"{V} called our office after receiving a text message from an unknown number, and I met {V.him} at {V.his} home to read it.\""), .direct("What did the text say?", "\"It said, 'You'll be sorry you called the sheriff.' {V} had saved it on the phone and showed me the full thread.\""), .direct("What did {V} tell you about why it was frightening?", "\"{V} said the sender knew about the earlier call to the sheriff, and {V.he} was afraid {V.he} was being watched.\""), .direct("How did you trace the number?", "\"A phone record showed the text came from {DL}'s number at 9:40 that evening, shortly after the earlier case was discussed.\""), .direct("What did {V} do with the message?", "\"{V} kept every message, took screenshots, and gave my office the phone so we could document the whole conversation.\""), .direct("What did {DL} say when you spoke with {D.him}?", "\"{D.He} said it was only meant to say that {V} would regret the trouble, and that {D.he} never planned to hurt anyone.\""), .cross("The text doesn't say how {V} would be sorry, does it?", "\"No, it doesn't describe any specific act. It says only that {V} would be sorry.\""), .cross("There was no mention of a weapon or an act of violence?", "\"No weapon is named, and the text doesn't say what would happen.\""), .cross("{DL} sent only one text?", "\"As far as the records show, it was one text message that evening.\""), .cross("{DL} didn't go to {V}'s house?", "\"No, I have no report that {D.he} went to the house or approached {V.him} in person.\""), .cross("{DL} cooperated with you?", "\"{D.He} did. {D.He} answered my questions and admitted sending the text without argument.\"")],
        theory: ("{D} threatened {V} for calling the sheriff.", "An angry text without a plan."),
        allocution: "\"I sent that text in anger, and I only meant that {V} would regret the trouble. I never planned anything, and I wouldn't hurt anyone. I've been in this courtroom before, and I know I should have kept quiet. I won't contact {V.him} again.\"",
        truths: ("{DL} drove past {V}'s house that night.", "The text was part of a longer exchange where {V} insulted {D}."),
        defendant: [.direct("Why did you send that message?", "\"I was angry that the sheriff had come to my door, and I wanted {V} to know that I was upset about it.\""), .direct("What did you mean by 'you'll be sorry'?", "\"I meant that {V} would regret the trouble that call caused. I never meant that I would hurt anyone.\""), .direct("Did you plan to do anything to {V}?", "\"No. I never planned anything. I sent it in anger one evening, and I didn't think about how it would sound.\""), .direct("What happened after you sent the text?", "\"I put the phone down and tried to calm myself. I didn't contact {V.him} again after that night.\""), .direct("How did you feel when the deputy came to see you?", "\"I felt ashamed. I told the deputy it was my text and that I shouldn't have sent it.\""), .direct("What would you say to {V} now?", "\"I'd say I'm sorry for scaring {V.him}, and that I'll stay away from {V.him} and keep my feelings to myself.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes. I knew how serious threats are, and I still let my anger get ahead of me that night.\""), .cross("You told {V} that {V.he} would be sorry?", "\"Yes, I wrote that, and I understand now how a person could read it as a threat.\""), .cross("You were angry at {V} for calling the sheriff?", "\"I was, and I shouldn't have been. {V.He} had a right to call for help if {V.he} felt unsafe.\""), .cross("{V} had no way to know you wouldn't act on it?", "\"That's true, and I regret that. I should have understood how frightening it would be to read.\""), .cross("You know that {V} kept the message and called deputies?", "\"Yes, I know. {V.He} did the right thing, and I'm the one who made that necessary.\"")],
        openings: ("{D} texted {V}, 'You'll be sorry you called the sheriff,' and {V} saved the message and called deputies. {DL} came before this court in {PRIORDATE} over {PRIOR}, and the phone record shows the text came from {D}'s own number at 9:40 p.m.", "The defense will say the text was an angry, empty line with no plan behind it. {D} meant that {V} would regret the trouble of involving the sheriff, not that {V.he} would be hurt, and nothing followed the message."),
        closings: ("The words were aimed at someone who had just called the sheriff, they came from {D}'s own phone, and they came after {D} had been warned by the earlier case over {PRIOR}. A reasonable person would take 'you'll be sorry' as a warning.", "One angry text, sent in the heat of the moment and never repeated, is not a threat the law punishes. {D} made no plan, took no step toward {V}, and the State must prove more than hurt feelings."),
        timeline: [(0, "9:40 p.m.: the text."), (1, "{V} shows deputies.")],
        identified: "{V}'s screenshot.",
        impact: "I haven't answered an unknown number since. The text said I'd be sorry I called the sheriff, and I read it in my kitchen with my kids in the next room. I kept every message and gave them to the deputies. I want to feel safe answering my own phone.",
        genders: ["D": .male])

    static let stalkingAtWork = SmallCases.make(
