        defense: [E(.statement, 1, "Locked Out", "{DL} says {D.he} was locked out and the porch light drew {D.him}.")],
        role: "Sheriff's deputy",
        exam: [.direct("What were you called to at two in the morning?", "\"A neighbor called about someone standing at the front door of {V}'s house, knocking, and {V} was afraid to open it.\""), .direct("What did you find when you arrived?", "\"{DL} was on the porch at the front door. {D.He} had been knocking for a few minutes and stopped when I pulled up.\""), .direct("What does the porch camera show?", "\"It shows {DL} arriving at two o'clock, standing at the door, knocking repeatedly, and looking in the window before leaving the porch.\""), .direct("Did {DL} have any reason to be there?", "\"{D.He} told me {D.he} was locked out of {D.his} own place, but {V}'s house is not {D.his} home.\""), .direct("What was the history with this address?", "\"{DL} had been warned in writing after the earlier case not to come onto {V}'s property.\""), .direct("What was {DL}'s condition?", "\"{D.He} was unsteady and smelled of alcohol, and {D.his} speech was slow, but {D.he} was able to answer my questions.\""), .cross("{DL} lives three doors down, doesn't {D.he}?", "\"Yes, {D.he} lives close by, which is why it's plausible {D.he} could have confused the houses.\""), .cross("{DL} didn't try to force the door?", "\"No. {D.He} knocked, and when no one answered, {D.he} stood there until I came.\""), .cross("{D.He} didn't run when you arrived?", "\"No. {D.He} stayed on the porch and spoke with me calmly.\""), .cross("The porch light was on?", "\"Yes, it was on, which is what {DL} said drew {D.him} to the door.\""), .cross("Nobody was hurt?", "\"No one was hurt and nothing was taken or damaged at the property.\"")],
        theory: ("{D} returned to the porch after a written warning.", "A locked-out neighbor."),
        allocution: "\"I'll call a locksmith next time. I locked myself out that night, and I was knocking on the wrong door, and I'm sorry for waking {V}. I've been in this courtroom before, and I know how it looks at two in the morning. I won't be back on that porch.\"",
        truths: ("{DL}'s own door was unlocked.", "{DL}'s key was found in a flower pot, and the lock had jammed."),
        defendant: [.direct("Why were you on {V}'s porch?", "\"I had locked myself out of my own house, and the porch light drew me to the nearest door in the dark.\""), .direct("Did you know whose house it was?", "\"I wasn't thinking clearly. I'd been out late, and I thought I was at a neighbor's who might let me use the phone.\""), .direct("Why were you knocking?", "\"I wanted to ask for help getting back inside. I never meant to frighten anyone, and I didn't try the handle.\""), .direct("Did you remember the written warning?", "\"I remembered it afterward. At the time, I wasn't thinking about the warning or about whose porch I was on.\""), .direct("What happened when the deputy arrived?", "\"I stopped knocking and told the deputy what had happened. I wasn't trying to hide, and I went with the deputy quietly.\""), .direct("What have you done since then?", "\"I gave a spare key to a friend and I don't go out drinking late. I don't want to wake anyone's household again.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I was told to stay away from that house. I broke that promise, even though I didn't mean to.\""), .cross("You knew you were warned not to enter that property?", "\"Yes, I knew about the warning. I just wasn't thinking about it at two in the morning.\""), .cross("You had been drinking that night?", "\"Yes, I had, and that's no excuse. It's the reason I made a bad decision.\""), .cross("You could have called someone from your own phone?", "\"I could have, but my phone was dead. I should have found another way.\""), .cross("{V} was frightened by the knocking?", "\"I understand that now, and I'm sorry. It was the wrong door at the wrong hour.\"")],
        openings: ("At two in the morning {D} was found on {V}'s porch again, standing at the front door and knocking, and the porch camera recorded it. {DL} had received a written warning after the earlier case over {PRIOR}.", "The defense will present a neighbor who locked {D.himself} out of {D.his} own home in the middle of the night. The porch light drew {D.him} to a familiar door, and {D.he} left when the deputy arrived."),
        closings: ("{D} had a written warning in hand after {PRIOR} and still came back to {V}'s door at two in the morning. The camera shows the knocking, and {V} was afraid to open the door to a person who had been warned off.", "A locked-out neighbor who knocked on the nearest lit porch made an honest mistake, not a threat. {D} stopped when the deputy pulled up, and the State must prove {D.he} knew {D.he} was not welcome."),
        timeline: [(0, "2 a.m.: {DL} at {V}'s front door."), (0, "{V} calls deputies.")],
        identified: "{V}'s porch camera.",
        impact: "I sleep with a bat now. At two in the morning someone stood at my front door knocking, and I didn't know who it was. It was the second time, and the same person. I lie awake listening. A porch should be the safest part of a home.",
        genders: ["D": .male])

    static let mailCardOpen = SmallCases.make(
        key: "story.followup.mailCardOpen",
        category: .whiteCollar,
        headlines: ["Card From Stolen Mail Used at Pharmacy", "Card Fraud Follows Mail Theft Case"],
        law: "cardFraud",
        spec: "Used a credit card belonging to {V}, a card issued in another person's name, to obtain $146 in goods, on {DATE}.",
        ages: 18...55,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V} reported a credit card mailed to {V.him} stolen. The card was used at a pharmacy for $146. The pharmacy camera showed {D}.",
        state: [E(.video, 3, "Pharmacy Camera", "{D} swipes the card at the register."), E(.document, 2, "Card Statement", "$146 charged within a day of the mailing.")],
        defense: [E(.statement, 1, "Gift Card", "{DL} says it was a gift card from a friend.")],
        role: "Pharmacist",
        exam: [.direct("How did you come to be involved in this case?", "\"The cardholder reported a credit card that was mailed to {V.him} had been stolen, and the bank flagged a purchase at our store.\""), .direct("What was purchased?", "\"Vitamins and a phone charger, for a total of one hundred forty-six dollars, paid with the card at the register.\""), .direct("What does the store camera show?", "\"It shows {DL} at the register swiping the card and walking out with the bag a few minutes later.\""), .direct("Did {DL} sign for the purchase?", "\"No signature was required for that amount, so there was no signature on the receipt to compare.\""), .direct("How did you identify {DL}?", "\"The camera still matched {DL}'s photograph, and a clerk recognized {D.him} as a customer who had been in before.\""), .direct("What did the card statement show?", "\"The statement showed the one hundred forty-six dollars charged within a day of the card being mailed to {V}.\""), .cross("{DL} was polite at the register?", "\"Yes, {D.he} was polite, and nothing about the transaction seemed unusual to the clerk.\""), .cross("You can't say how {DL} got the card?", "\"No, I can only say what the camera showed at the register. I don't know where the card came from.\""), .cross("The purchases were small items?", "\"Yes, vitamins and a phone charger. Nothing that would draw attention at the register.\""), .cross("The card wasn't used again at your store?", "\"No. As far as I know, it was only used that one time at our store.\""), .cross("{DL} never denied being there?", "\"No, {D.he} acknowledged being at the store when the deputy asked about it.\"")],
        theory: ("{D} used a card taken from the mail.", "A gift card from a friend."),
        allocution: "\"A friend gave me that card, and I used it at the pharmacy without thinking about where it came from. I've been in this courtroom before and I should have known better. I'm sorry to {V}, and I'll cover the one hundred forty-six dollars.\"",
        truths: ("The card's envelope was found in {DL}'s trash.", "The 'friend' was never found."),
        defendant: [.direct("Where did you get that card?", "\"A friend gave it to me and told me it was a gift card with money on it. I didn't read the name on it.\""), .direct("Why did you use it at the pharmacy?", "\"I needed vitamins and a phone charger, and I thought I was spending money my friend had given me.\""), .direct("Did you know it was stolen?", "\"No. If I had known it came out of someone's mailbox, I would never have touched it.\""), .direct("Did you look at the name on the card?", "\"It looked like a regular card, and I didn't think about the name or whether it matched mine.\""), .direct("What did you do when you learned the truth?", "\"I told the deputy who gave it to me, and I offered to pay back the one hundred forty-six dollars.\""), .direct("What would you tell the court?", "\"I'm sorry for what happened to {V}. I should have asked questions before I used a card that wasn't mine.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I should have known better than to use a card I hadn't checked. That's on me.\""), .cross("The card had someone else's name on it?", "\"It did, and I didn't look at it. I should have.\""), .cross("You used it at a store where you were known?", "\"Yes. That's one more reason I wasn't thinking it was stolen. I wasn't hiding anything.\""), .cross("Your friend told you it was a gift card?", "\"Yes, that's what I was told, and I believed it without asking more.\""), .cross("You'll repay the one hundred forty-six dollars?", "\"Yes, I will, and I'll give the court a way to make sure it's paid.\"")],
        openings: ("{V} reported that a credit card mailed to {V.him} had been stolen, and the bank flagged a $146 purchase at a pharmacy the next day. The pharmacy camera shows {D} swiping the card at the register. {DL} had been here before over {PRIOR}.", "The defense will present a gift card from a friend. {D} believed the card was a present, used it as one, and had no idea it had been taken from anyone's mailbox before it reached {D.him}."),
        closings: ("The card was mailed to {V}, never reached {V}, and was used within a day for $146 at a store where the camera shows {D}. After {PRIOR}, {D} knew the difference between a gift and someone else's card.", "A friend's gift looks like any other card in a wallet, and {D} used it openly in front of a camera. A person using a stolen card behaves differently, and the State has not shown that {D} knew where it came from."),
        timeline: [(0, "Afternoon: the card is used."), (1, "{V} sees the charge.")],
        identified: "The pharmacy camera.",
        impact: "I lost three days getting my credit straightened out. A card that was mailed to me was stolen from my box, and a stranger spent a hundred forty-six dollars at a pharmacy. I spent hours on the phone with the bank and the credit bureaus. I'd never thought about my mail being a risk.",
        genders: ["D": .male])

    static let siphonTwo = SmallCases.make(
        key: "story.followup.siphonTwo",
        category: .property,
        headlines: ["Another Siphoning Case for Same Man", "Hose and Can Found Again at Dawn"],
        law: "misdLarceny",
        spec: "Stole about fifteen gallons of diesel fuel valued at $60 from a truck belonging to {V}, on {DATE}.",
        ages: 20...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V} found {D} at {V.his} work truck at dawn with a hose and a can. {DL} says {V} lets people borrow.",
        state: [E(.physical, 3, "Hose and Can", "A hose in the tank and a full can.", .search), E(.statement, 2, "{V}", "{V} says {V.he} never lends diesel.")],
        defense: [E(.statement, 1, "Borrowing", "{DL} says {V} lets people borrow.")],
        role: "Sheriff's deputy",
        exam: [.direct("What did you find at the truck that morning?", "\"{DL} was standing at {V}'s work truck at dawn with a hose in the fuel tank and a full can at {D.his} feet.\""), .direct("How did the call come in?", "\"{V} was getting ready for work and saw someone at the truck from the window, and called the sheriff's office right away.\""), .direct("What did you do with the hose and can?", "\"I photographed them where they were, then took them into evidence. The can held about fifteen gallons of diesel fuel.\""), .direct("What did {V} tell you about lending fuel?", "\"{V} said {V.he} never lends diesel to anyone because it's expensive and the truck is how {V.he} makes a living.\""), .direct("What did {DL} tell you?", "\"{D.He} said {V} lets people borrow what they need, and that {D.he} had permission in the past.\""), .direct("What was the value of the fuel?", "\"About sixty dollars at the price that week, and the tank was left low enough to delay the day's first job.\""), .cross("{DL} didn't run when you arrived?", "\"No. {D.He} stayed where {D.he} was and answered my questions.\""), .cross("{V} and {DL} are neighbors?", "\"They know each other, and {V} has helped people around there before, which is why {DL} said it was allowed.\""), .cross("You didn't see {DL} take the fuel?", "\"I saw the hose in the tank and the can, but I didn't watch the siphoning from the start.\""), .cross("{DL} told you {V} had said yes before?", "\"Yes, {D.he} said that, but {V} denied giving permission this time or for diesel fuel.\""), .cross("The fuel was returned or valued?", "\"The fuel was never returned. It was valued for the restitution request at about sixty dollars.\"")],
        theory: ("{D} siphoned diesel from a different truck.", "A man who thought borrowing was fine."),
        allocution: "\"No more siphoning. I was there early, and I figured {V} wouldn't mind because folks borrow from each other around here. I know I should have asked, and I've been in this courtroom before. I'm sorry, and I'll replace every gallon I took.\"",
        truths: ("{DL} had a list of trucks on a notepad.", "{V} had waved {DL} over a week earlier to take a little."),
        defendant: [.direct("What were you doing at {V}'s truck?", "\"I needed fuel for my own truck, and I thought {V} wouldn't mind because folks borrow from each other around here.\""), .direct("Did you ask {V} first?", "\"Not that morning. It was early, and I didn't want to wake {V.him}. I figured I could settle up later.\""), .direct("Why did you think it was allowed?", "\"Last week {V} had said I could use some of what {V.he} had. I took that to mean the same would be fine again.\""), .direct("What was in the can?", "\"About fifteen gallons of diesel that I had pumped out of {V}'s tank. I meant to replace it before {V.he} noticed.\""), .direct("What happened when the deputy arrived?", "\"I told the deputy exactly what I'd done. I didn't try to hide the hose or the can, and I stayed put.\""), .direct("What do you intend to do about it now?", "\"I'll pay for the fuel and apologize to {V}. I won't take anything from {V.him} again without asking first.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I know better than to take what isn't mine. I let the habit of borrowing get ahead of the rules.\""), .cross("{V} told you not to touch the diesel?", "\"{V.He} told me that after the fact. I understand now that I should have asked every time.\""), .cross("You took fifteen gallons without anyone present?", "\"Yes, early in the morning when no one was there. I know how that looks.\""), .cross("{V} depends on that truck for work?", "\"Yes, and I'm sorry for the delay it caused. I never thought about how much {V.he} needed that fuel.\""), .cross("You'll replace every gallon?", "\"I will, and I'll bring the receipts to show it. I'd rather settle it than argue.\"")],
        openings: ("{V} saw {D} at {V.his} work truck at dawn with a hose in the fuel tank and a full can at {D.his} feet, and called the sheriff's office at once. {DL} had been before this court over {PRIOR}, and {V} says {V.he} never lends diesel.", "The defense will say {V} lets people borrow what they need, and {D} understood that fuel was one of those things. {D} was not sneaking; {D.he} was taking what {D.he} thought {D.he} was free to take."),
        closings: ("{V} never lent {D} diesel, and a hose in a fuel tank at dawn is no borrowing. {DL} had already stood here over {PRIOR} and could not have believed {V} approved of this.", "A man who believed that borrowing was fine in this neighborhood made a mistake about permission, not a plan to steal. {V} never told {D} no, and the State must prove otherwise beyond a reasonable doubt."),
        timeline: [(0, "5 a.m.: {DL} at the truck."), (0, "{V} calls deputies.")],
        identified: "{V} found {D} at the truck.",
        impact: "My work truck is how I make a living, and a drained tank means a lost morning. I found someone at the truck at dawn with a hose and a can. I can't be at every job if I'm waiting on fuel. It cost me my schedule and some good will.",
        genders: ["D": .male])

    static let windshieldCrack = SmallCases.make(
        key: "story.followup.windshieldCrack",
        category: .property,
        headlines: ["Windshield Smashed on the Same Car", "Second Property Damage Case After Slashed Tires"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, a car, by smashing the windshield, causing damage of $520, on {DATE}.",
        ages: 21...52,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V}'s windshield was smashed with a tire iron. A neighbor's camera showed a man in a gray jacket. {D} says {D.he} was at work.",
        state: [E(.video, 3, "Neighbor's Camera", "A man in a gray jacket swings a tire iron at the windshield."), E(.document, 2, "Estimate", "$520 for glass and labor.")],
        defense: [E(.statement, 1, "Time Clock", "{DL}'s work time clock shows {D.him} on shift at 2 a.m.")],
        role: "Sheriff's deputy",
        exam: [.direct("What did the neighbor's camera show?", "\"It shows a man in a gray jacket walking up to {V}'s car and swinging a tire iron at the windshield at about two in the morning.\""), .direct("Can you see the man's face?", "\"No. The camera is some distance away, and the hood on the jacket hides most of the face.\""), .direct("What damage did you document?", "\"The windshield was shattered with a point of impact near the center, and I photographed the glass and the tire iron marks.\""), .direct("What did the repair estimate say?", "\"Five hundred twenty dollars for the glass and labor, which was what {V} was quoted at the shop.\""), .direct("Why did you look at {DL}?", "\"{DL} and {V} had a dispute after the earlier case, and {DL} owns a gray jacket like the one in the video.\""), .direct("What did {DL} tell you?", "\"{D.He} said {D.he} was at work that night and denied having anything to do with the damage.\""), .cross("You can't identify the man on the video?", "\"No. His face is not visible, and I can only describe the clothing and the tire iron.\""), .cross("Many people own a gray jacket?", "\"Yes. It's a common type of jacket, and I can't say it belongs to anyone in particular.\""), .cross("{DL}'s time clock shows {D.him} on shift at two a.m.?", "\"Yes, the work records show {D.him} clocked in during that hour, and I haven't disproved that.\""), .cross("You never found the tire iron?", "\"No, we never recovered the tire iron, so there's nothing physical tying it to {DL}.\""), .cross("The video doesn't show a car?", "\"The video shows a person on foot, and no vehicle was captured in that clip.\"")],
        theory: ("{D} returned to damage {V}'s car again.", "A man on shift at the time."),
        allocution: "\"I'll stay away from {V}. I was at work that day, on shift, and I didn't break that windshield. I've been in this courtroom before, and I know it's easy to point at me. I'm sorry for the damage, and I ask the court to check the time records.\"",
        truths: ("{DL} had left the clock station at 1:30 and returned at 2:20.", "The time clock was being used by a coworker to punch in for {DL}."),
        defendant: [.direct("Where were you at two in the morning?", "\"I was at work on my regular overnight shift. My time card shows I clocked in at ten and out at six.\""), .direct("Did you leave the building that night?", "\"No. I stayed at my station and took my breaks in the break room with the others working that shift.\""), .direct("Do you own a gray jacket?", "\"Yes, like a lot of people, but it was hanging in my locker at work that night.\""), .direct("Did you break {V}'s windshield?", "\"No. I would never do that. I had no reason to damage {V.his} car, and I wasn't there.\""), .direct("What did you tell the deputy?", "\"I told the deputy I was at work and gave the name of my supervisor so the deputy could confirm it.\""), .direct("What would you ask the court to do?", "\"I ask the court to check the time records and talk to my supervisor before deciding that I'm the man on that video.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I understand why people look at me first. That doesn't mean I did this.\""), .cross("You and {V} had a dispute?", "\"We had words after the earlier case, but it was never about the car and I let it go.\""), .cross("The man in the video wore a gray jacket like yours?", "\"Like mine, and like hundreds of others. The video doesn't show anything that proves it's mine.\""), .cross("You could have clocked in and left?", "\"Not without being noticed. The building has cameras and a supervisor on the floor.\""), .cross("You'd like the court to check the records?", "\"Yes, please. The time clock and the supervisor will show I was at work.\"")],
        openings: ("A neighbor's camera shows a man in a gray jacket swing a tire iron at {V}'s windshield at about two in the morning, a repair that cost $520. {D} came before this court in {PRIORDATE} over {PRIOR}, and {V} believes it was {D} again.", "The defense will present {D}'s work time clock, which shows {D.him} on shift at the hour of the damage. The camera shows a hooded man at a distance, and no one can see a face."),
        closings: ("{D} had already been here over {PRIOR}, and the same jacket, the same neighborhood, and the same target point back to {D}. The State will connect the man on the camera to the man in the courtroom.", "The hood hides the face, the camera is far away, and the time clock puts {D} at work when the glass was broken. A grainy figure in a gray jacket is not proof of who swung the iron."),
        timeline: [(0, "2 a.m.: the windshield is smashed."), (0, "Morning: {V} reports the damage.")],
        identified: "{V}'s guess and a neighbor's camera.",
        impact: "Both times I couldn't get to work. First the windshield was smashed with a tire iron, and then I had to wait for the glass shop. I missed a day's pay each time. A neighbor's camera caught someone in a gray jacket, and it still bothers me.",
        genders: ["D": .male])

    static let tailgateThreat = SmallCases.make(
        key: "story.followup.tailgateThreat",
        category: .publicOrder,
        headlines: ["Threat at Next Home Game for Man in Shove Case", "Communicating Threats After Tailgate Dispute"],
        law: "communicatingThreats",
        spec: "Willfully threatened to physically injure {V}, in a manner a reasonable person would believe would be carried out, on {DATE}.",
        ages: 24...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} saw {V} at the next home game and said, 'Next time I won't push, I'll hit.' A parent heard it.",
        state: [E(.statement, 3, "Parent", "A parent heard 'next time I'll hit.'"), E(.document, 2, "Stadium Report", "An incident report filed by the resource officer.")],
        defense: [E(.statement, 1, "Joke", "{DL} says it was a joke between men.")],
        role: "School resource officer",
        exam: [.direct("What were you asked about at the game?", "\"A parent told me that during the home game someone said a threat to {V}, and I wrote an incident report.\""), .direct("What did the parent say they heard?", "\"The parent said {DL} said to {V}, 'Next time I won't push, I'll hit,' and that it was loud enough to hear.\""), .direct("Where was this said?", "\"In the parking lot beside the field after the game, with parents and students standing nearby.\""), .direct("What did you do?", "\"I separated them, spoke to both, and wrote an incident report that I turned over to the sheriff's office the next day.\""), .direct("How did {V} react?", "\"{V} was shaken, said {V.he} was afraid for {V.his} safety, and asked me to document it so there would be a record.\""), .direct("What did {DL} say when you spoke to {D.him}?", "\"{D.He} said it was a joke between men and that {D.he} never meant to hurt anyone.\""), .cross("There was an earlier shove between them, wasn't there?", "\"Yes, that was the case before this court, and the statement refers to it.\""), .cross("{DL} didn't touch {V} that night?", "\"No. There was no physical contact at the game, only the words.\""), .cross("The parent was standing nearby, not right beside them?", "\"A few feet away, close enough to hear, but not directly between them.\""), .cross("Other people didn't report hearing it?", "\"One parent reported it. I didn't get statements from anyone else that night.\""), .cross("{DL} left when you told {D.him} to?", "\"Yes, {D.he} left without any argument when I asked {D.him} to go home.\"")],
        theory: ("{D} threatened to hit {V} at the next game.", "A joke."),
        allocution: "\"I said that to {V} at the game because I was being needled, and I didn't mean it. I've been in this courtroom before, and I know words can hurt. A parent heard me, and I'm ashamed. I'll stay away from {V.him} and those games.\"",
        truths: ("{DL} walked toward {V} after saying it.", "{V} had smirked and said 'try it.'"),
        defendant: [.direct("What did you say to {V}?", "\"I said something like 'next time I won't push, I'll hit.' I said it as a jab, and I shouldn't have.\""), .direct("Why did you say it?", "\"{V} had been needling me about the earlier case in front of other people, and I let it get to me.\""), .direct("Did you mean it?", "\"No. It was something I said in the heat of the moment and not something I planned to do.\""), .direct("What was going through your mind?", "\"I was embarrassed and angry in front of the other parents, and I said the worst thing that came into my head.\""), .direct("What happened after you spoke?", "\"The resource officer separated us, and I left the lot. I haven't contacted {V} since.\""), .direct("What would you say to {V}?", "\"I'm sorry for frightening {V.him}, and I'll keep my distance. I won't go near {V.him} at those games again.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, over the earlier shove. I knew better than to say something like that to the same person.\""), .cross("You said you would hit {V}?", "\"I said it, and I know how it sounded. I didn't mean it, but I understand why it was frightening.\""), .cross("A parent heard you say it?", "\"Yes, and I'm ashamed that a parent had to hear that at a school game.\""), .cross("You called it a joke?", "\"I did, and it was a bad one. It wasn't funny to {V}, and it shouldn't have been said.\""), .cross("You'll stay away from {V} and those games?", "\"Yes. I'll watch from somewhere else, or I won't go at all if it keeps the peace.\"")],
        openings: ("At the next home game {D} told {V}, 'Next time I won't push, I'll hit,' loud enough for a parent to hear. {DL} had been before this court over {PRIOR}, and the resource officer wrote an incident report that same day.", "The defense will say the remark was a joke between men, the kind of rough talk that goes around a football field. {D} never raised a hand, and no one in the stands treated it as a serious threat."),
        closings: ("After the earlier case over {PRIOR}, {D} promised to 'hit' next time, in a crowd, to the person {D.he} had pushed before. A parent heard it, and the officer's report records it.", "A joke between men is not a threat, and {D} followed it with nothing. The State has to prove {D} meant {V} to believe harm was coming, and the words alone, said loosely, do not prove that."),
        timeline: [(0, "Friday evening: the next home game."), (0, "The threat in the parking lot.")],
        identified: "A parent and the resource officer.",
        impact: "I park on the other side of the lot now. At the game I heard {D.him} say next time {D.he} wouldn't push, {D.he}'d hit. A parent next to us heard it, too. I coach kids on weekends, and I shouldn't have to look over my shoulder when I'm doing it.",
        genders: ["D": .male])

    static let falseNameResisting = SmallCases.make(
        key: "story.followup.falseNameResisting",
        category: .publicOrder,
        headlines: ["Man Gave a Fake Name Again, Charged With Resisting", "Second False Name at a Traffic Stop"],
        law: "resisting",
        spec: "Willfully resisted, delayed, and obstructed a public officer by giving a false name, on {DATE}.",
        ages: 19...50,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} gave a deputy the name of a different man at a roadside stop. A fingerprint check at the jail revealed the truth again.",
        state: [E(.video, 3, "Body Camera", "{D} gives a false name and birth date."), E(.document, 2, "Fingerprint Record", "The prints belong to {D}.")],
        defense: [E(.statement, 1, "Nickname", "{DL} says the name is a nickname.")],
        role: "Sheriff's deputy",
        exam: [.direct("What were you doing at the roadside that night?", "\"I stopped a vehicle for a traffic violation and asked the driver for a license and registration.\""), .direct("What name did the driver give you?", "\"The driver gave me a name that wasn't {DL}'s and a birth date to go with it.\""), .direct("What does your body camera show?", "\"It shows the driver giving the false name and birth date clearly and repeating them when I asked a second time.\""), .direct("How did you learn the truth?", "\"At the jail, a fingerprint check came back to {DL}, and the prints matched the earlier record in this court.\""), .direct("Why does giving a false name matter?", "\"It delays the stop, makes it harder to check for warrants, and can put officers and the public at risk.\""), .direct("What did {DL} say when confronted?", "\"{D.He} said the name is a nickname {D.he} goes by, though the birth date wasn't {D.his}.\""), .cross("{DL} was calm during the stop?", "\"Yes, {D.he} was calm and polite, and didn't try to flee or argue with me.\""), .cross("The name given is a name {DL} has been called?", "\"{D.He} said so, but I found nothing in any records connecting that name to {D.him}.\""), .cross("You didn't ask for ID that night?", "\"I asked for a license, and {DL} said {D.he} didn't have it with {D.him}.\""), .cross("The fingerprints were what proved who it was?", "\"Yes. That's how we confirmed the identity, since the name given led nowhere.\""), .cross("{DL} gave the correct name after the prints?", "\"Yes, once the prints came back, {D.he} acknowledged who {D.he} was.\"")],
        theory: ("{D} gave a false name for the second time.", "A nickname."),
        allocution: "\"I'll give my real name from now on. It's a nickname I've gone by for years, and I was nervous at that stop and gave it. I'm sorry I wasted the deputy's time. I've been in this courtroom before, and I'll be honest at every stop.\"",
        truths: ("{DL} had used the name at a previous stop.", "The name was {D.his} middle name and a family nickname."),
        defendant: [.direct("Why did you give that name?", "\"It's a nickname I've gone by for years, and I said it out of habit when the deputy asked me.\""), .direct("Why did you give a different birth date?", "\"I was nervous and gave the first date that came to mind. I wasn't thinking clearly at the stop.\""), .direct("Did you mean to mislead the deputy?", "\"I didn't mean to cause trouble. I panicked because I had been in court before and didn't want more problems.\""), .direct("What happened at the jail?", "\"They took my fingerprints and the real name came up. I told them who I was right away.\""), .direct("Do you understand why this is wrong?", "\"Yes. Giving a false name makes the deputy's job harder, and I should have told the truth immediately.\""), .direct("What will you do from now on?", "\"I'll give my real name at every stop and carry my license, so that I'm honest and there's no confusion.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I knew how it looked to give a different name. That's why I regret it so much.\""), .cross("You gave a name that wasn't yours?", "\"It's a nickname, but I gave it as if it were my legal name, and I know that wasn't right.\""), .cross("The birth date was wrong too?", "\"Yes, and I have no good explanation for it except that I was nervous and frightened.\""), .cross("You corrected it only after the fingerprints?", "\"That's right. I should have corrected it the moment I realized how it sounded.\""), .cross("You'll be honest at every stop from now on?", "\"I will, and I'll keep my license with me so there's never any question.\"")],
        openings: ("At a roadside stop {D} gave the deputy the name and birth date of another man, and the body camera recorded it. A fingerprint check at the jail revealed the truth. {DL} had been here before over {PRIOR}.", "The defense will say the name {D} gave is a nickname {D.he} has used for years, not an attempt to deceive. {D.He} gave what {D.he} is called, and the deputy took it as a false identity."),
        closings: ("{D} gave a false name for the second time, after already facing {PRIOR} in this court. The body camera captures the lie, and the fingerprints on file belong to {D}, not to the man {D.he} named.", "A nickname is not a disguise, and {D} did not run or resist when the prints came back. The State must show a deliberate false name, and what the camera shows is a name familiar to {D}."),
        timeline: [(0, "Afternoon: a traffic stop."), (0, "The jail's fingerprints reveal {D}.")],
        identified: "Jail fingerprints.",
        genders: ["D": .male])

    static let copperScrapYard = SmallCases.make(
        key: "story.followup.copperScrapYard",
        category: .property,
        headlines: ["Copper Wire Sold at Scrap Yard After Vacant House Case", "Stolen Copper Flagged at Scrap Yard"],
        law: "possStolen",
        spec: "Possessed copper wiring valued at $340 belonging to {V}, knowing and having reasonable grounds to believe it stolen, on {DATE}.",
        ages: 20...58,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} sold 40 pounds of stripped copper wire at the same scrap yard. {V}'s vacant rental had been stripped of wiring.",
        state: [E(.document, 3, "Scrap Yard Ticket", "{D}'s ID on a ticket for 40 pounds of copper wire."), E(.physical, 2, "Photos", "Cut wire ends in {V}'s walls.")],
        defense: [E(.statement, 1, "Bought Scrap", "{DL} says {D.he} bought the copper cheaply.")],
        role: "Scrap yard clerk",
        exam: [.direct("How did {DL} come to your yard that day?", "\"{DL} came in with about forty pounds of stripped copper wire and asked for it to be weighed and paid on the scale.\""), .direct("What do you ask a seller to do?", "\"State law requires ID and a signed ticket, so I copied {D.his} license and had {D.him} sign the scrap ticket.\""), .direct("What was the copper like?", "\"It was clean, stripped wire with cut ends, the kind that comes out of walls or panels and not from old appliances.\""), .direct("What did you pay?", "\"I paid three hundred forty dollars on the ticket, which was the going rate for forty pounds of clean copper that week.\""), .direct("How did the sheriff's office get involved?", "\"{V} reported a vacant rental stripped of wiring, and a detective checked the yards for recent tickets matching the amount.\""), .direct("What did you tell the detective?", "\"I told the detective who sold it, showed the ticket with the license number, and let the deputy see the wire.\""), .cross("Scrap yards buy copper from all kinds of people, don't they?", "\"Yes, we buy from contractors, electricians, and individuals every day. Most are completely legitimate.\""), .cross("{DL} showed identification and signed the ticket?", "\"Yes, {D.he} showed a driver's license and signed without hesitating, which is not what people hiding something usually do.\""), .cross("You can't say where the wire came from?", "\"No. I only know what {D.he} brought in. I have no way to tell which building it came out of.\""), .cross("The wire had no markings tying it to {V}'s building?", "\"That's right. It was ordinary stripped copper with nothing that identified the property it came from.\""), .cross("{DL} told you where the wire came from?", "\"{D.He} said {D.he} bought it cheap from someone, but I didn't write that down and wasn't told a name.\"")],
        theory: ("{D} sold copper stripped from a vacant house.", "A flipper."),
        allocution: "\"I'll stop buying scrap. I got that copper from a man at a flea market and paid cash, and I took it to the same yard I always do. I didn't think about where it came from. I'm sorry to {V}, whose house was stripped, and I'll help however I can.\"",
        truths: ("The cut ends matched {V}'s wiring.", "The seller who sold the copper to {DL} was arrested later."),
        defendant: [.direct("Where did you get the copper?", "\"I bought it from a man at a flea market for a good price. He said he'd pulled it from a job he was cleaning out.\""), .direct("Why did you take it to the scrap yard?", "\"I do odd jobs and always need money, and I knew the yard pays well for clean wire.\""), .direct("Did you know it came from {V}'s rental?", "\"No. I had never heard of {V.him} or that building. I thought it came from a legitimate cleanout.\""), .direct("Why did you use your own ID?", "\"I had nothing to hide. I showed my license and signed because I believed what I was selling was legitimate.\""), .direct("What did you pay for it?", "\"About one hundred dollars. I thought it was a good deal, and I didn't ask enough questions about it.\""), .direct("What happened when the detective talked to you?", "\"I told the detective everything I knew about the man, though I never had his name or number.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I should have been more careful about where I got things. That's what I regret most.\""), .cross("You paid far less than the yard paid you?", "\"Yes, and that should have been a sign. I told myself it was a lucky find.\""), .cross("You can't name the seller?", "\"I can't. I met him at the flea market once and never got his name or a way to reach him.\""), .cross("Stripped wire like that usually comes out of walls?", "\"I know that now. At the time I thought it was left over from a rewiring job.\""), .cross("You didn't ask for a receipt?", "\"No. I should have asked for proof he owned it, and I'm sorry I didn't.\"")],
        openings: ("{D} sold forty pounds of stripped copper wire at the scrap yard, with {D.his} ID on the ticket. {V}'s vacant rental had been stripped of its wiring, and the cut wire ends in the walls match what was weighed. {DL} was here before over {PRIOR}.", "The defense will present a man who flips scrap for a living and bought the copper cheaply from someone else. {D} had no idea where it came from, and showed ID and signed the ticket like any honest seller."),
        closings: ("Forty pounds of stripped copper, sold by {D}, from a rental that had been gutted. After {PRIOR}, {DL} could not have missed what stripped wire from an empty house usually means.", "A man who shows ID and signs a ticket is not hiding anything. {D} bought low and sold for a small margin like any reseller, and the State has not shown {D} knew the copper was stolen."),
        timeline: [(0, "Weekend: the wiring is stripped."), (2, "Monday: {DL} sells the copper.")],
        identified: "The scrap yard's ticket.",
        impact: "The house lost four thousand dollars in wiring. I'd just finished repairs on that rental and was waiting on a tenant. The electrician said every wall had been cut. I've put in new wire twice now. I'm not sure the house will ever pay for itself.",
        genders: ["D": .male])

    static let laptopPhoneTwo = SmallCases.make(
        key: "story.followup.laptopPhoneTwo",
        category: .property,
        headlines: ["Phone Pawned After Laptop Case", "Stolen Phone Traced to Pawn Shop Seller"],
        law: "possStolen",
        spec: "Possessed a cellular telephone valued at $620 belonging to {V}, knowing and having reasonable grounds to believe it stolen, on {DATE}.",
        ages: 18...45,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} pawned a phone reported stolen from a student at a campus coffee shop. {DL} says {D.he} bought it for $60.",
        state: [E(.document, 3, "Pawn Ticket", "{D}'s ID on a ticket for the phone."), E(.digital, 2, "Find My Phone", "The phone's location matched the pawn shop.")],
        defense: [E(.statement, 1, "Bought Phone", "{DL} says {D.he} bought it from a man.")],
        role: "Pawn shop clerk",
        exam: [.direct("How did the phone come into your shop?", "\"{DL} came in and pawned a phone, showed a license, and signed the pawn ticket for sixty dollars.\""), .direct("What do you do when you take a phone?", "\"I log the make, model, and serial number, scan the license, and report it to the pawn database the same day.\""), .direct("What did the database show?", "\"The serial number matched a phone reported stolen from a student at a campus coffee shop only days earlier.\""), .direct("What did the phone's location show?", "\"The student's find-my-phone app placed the phone at our shop, which led deputies straight to the counter.\""), .direct("What was the phone worth?", "\"It was a recent model valued at about six hundred twenty dollars, and {DL} accepted sixty.\""), .direct("What did {DL} say about where it came from?", "\"{D.He} said {D.he} bought it from a man for about sixty dollars and didn't know it was stolen.\""), .cross("{DL} used {D.his} real ID at your counter?", "\"Yes. {D.He} showed a valid license and signed the ticket in {D.his} own name.\""), .cross("Someone who knew a phone was stolen might use a false name?", "\"Many do, yes. {DL} did not, though I can't say what that proves.\""), .cross("You pay less than a phone is worth?", "\"Of course. Pawn loans are a fraction of value, so the amount alone doesn't tell me much.\""), .cross("You don't know who sold it to {DL}?", "\"No, I have no information about that. I only know what {D.he} told me and what the ticket shows.\""), .cross("{DL} cooperated when deputies came?", "\"Yes, {D.he} came in, spoke to the deputies, and didn't try to avoid them.\"")],
        theory: ("{D} pawned another stolen device.", "A buyer."),
        allocution: "\"I won't buy things from strangers anymore. I paid sixty dollars for that phone, and I took it to a pawn shop because I needed the money. I never knew it was stolen. I'm sorry to the student, and I'll return it.\"",
        truths: ("The same man who sold {DL} the laptop sold the phone.", "{DL} had been told by the pawn shop to check devices."),
        defendant: [.direct("Where did you get the phone?", "\"I bought it from a man outside a convenience store for sixty dollars. He said it was his old phone.\""), .direct("Why did you buy it?", "\"Mine was broken and I couldn't afford a new one. Sixty dollars for a phone that worked seemed like a fair deal.\""), .direct("Why did you pawn it?", "\"I needed rent money, and I decided the phone wasn't worth the trouble of fixing up and selling myself.\""), .direct("Did you know it was stolen?", "\"No. If I had known it belonged to a student, I would have returned it, and I never would have pawned it.\""), .direct("What happened when the deputies came?", "\"I told them everything. I gave them the description of the man and where I bought the phone.\""), .direct("What would you say to the owner?", "\"I'm sorry the phone was taken, and I'm sorry I got involved. I hope the owner gets it back.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I should have known to be careful about buying things off the street.\""), .cross("You paid sixty dollars for a six-hundred-dollar phone?", "\"Yes, and I knew it was cheap. I told myself I'd found a bargain, and that was wrong.\""), .cross("You didn't ask for any proof it was his?", "\"I didn't. I took his word for it and I shouldn't have.\""), .cross("You can't give a name for the seller?", "\"No, I never got a name. It was a quick sale and I didn't think I'd need it.\""), .cross("You used your own ID at the pawn shop?", "\"Yes, I had nothing to hide. I thought I was selling something I'd bought honestly.\"")],
        openings: ("{D} pawned a phone reported stolen from a student at a campus coffee shop, showed a license, and signed the pawn ticket for $60. The phone's own tracking matched the pawn shop, and {DL} had been before this court in {PRIORDATE} over {PRIOR}.", "The defense will say {D} bought the phone from a man for sixty dollars and pawned it as an ordinary buyer would. {D} had no idea it was stolen, and used {D.his} own ID throughout."),
        closings: ("A phone stolen from a student ended up at a pawn shop under {D}'s signature. After {PRIOR}, {DL} knew a cheap phone from a stranger deserved a question, and the tracking shows exactly where it went.", "A man who pawns with {D.his} own license and signs {D.his} own name is not acting like a thief. {D} bought a phone from a man and did not know better, and the State must prove otherwise."),
        timeline: [(0, "Afternoon: the phone is pawned."), (1, "The student tracks it to the shop.")],
        identified: "The pawn shop's flag.",
        impact: "My photos and my two-factor codes were on it. I put the phone down for a minute at a campus coffee shop and it was gone. I couldn't get into my accounts for days. My whole semester of notes was in there. I felt completely exposed.",
        genders: ["D": .male])

    static let returnFraudTwo = SmallCases.make(
        key: "story.followup.returnFraudTwo",
        category: .whiteCollar,
        headlines: ["Second Return Scheme at Another Store", "Receipt Check Ends Another Return"],
        law: "falsePretenses",
        spec: "Obtained $212 in store credit from a retail store by falsely representing that merchandise had been purchased, on {DATE}.",
        ages: 24...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} returned a set of cookware at another store with a receipt that didn't match. Security tags were still on.",
        state: [E(.document, 3, "Receipts", "The receipt is for a different purchase."), E(.physical, 2, "Tags", "Security tags still on.")],
        defense: [E(.statement, 1, "Gift", "{DL} says the cookware was a gift.")],
        role: "Department store loss prevention manager",
        exam: [.direct("What drew your attention to {DL}?", "\"{DL} came to the service desk to return a cookware set, and the receipt didn't match the item or the store.\""), .direct("What was wrong with the receipt?", "\"It was for a different purchase on a different day, and it listed items that weren't the cookware in the box.\""), .direct("What about the cookware itself?", "\"The security tags were still attached to the pieces, which means the set had not been purchased and checked out.\""), .direct("What was {DL} asking for?", "\"{D.He} asked for two hundred twelve dollars in store credit for the set.\""), .direct("What did you do?", "\"I held the return, called our loss prevention office, and then called the sheriff's office as our policy requires.\""), .direct("What did {DL} say about the cookware?", "\"{D.He} said it was a gift and {D.he} didn't have the correct receipt, so {D.he} used the one in the bag.\""), .cross("People return gifts without receipts all the time, don't they?", "\"They do, and we handle those with ID and a lower credit. {DL} presented a receipt for something else.\""), .cross("{DL} didn't leave the store with the cookware?", "\"Correct. The set stayed at the service desk and nothing was paid out.\""), .cross("{DL} wasn't hiding from the staff?", "\"No, {D.he} came to the desk openly and spoke with us at the counter.\""), .cross("The security tags could have been missed at checkout?", "\"It's possible on a gift, but the tags are removed when an item is bought, and these hadn't been.\""), .cross("You can't say who sold the set originally?", "\"No. I only know it wasn't sold at our store, since our tags don't match a gift purchase.\"")],
        theory: ("{D} returned stolen goods again.", "A gift."),
        allocution: "\"A friend gave me that cookware as a gift, and I tried to return it without knowing the receipt didn't match. The tags were still on. I'm sorry to the store.\"",
        truths: ("{DL}'s friend worked at a different store and sold {D.him} receipts.", "The friend gave {DL} a bag of items and receipts."),
        defendant: [.direct("Where did the cookware come from?", "\"A friend gave it to me as a gift when I moved into my apartment, and it wasn't what I needed.\""), .direct("Why did you use that receipt?", "\"It was in the box with the set, and I thought it went with it. I didn't read it closely.\""), .direct("Did you know the tags were still on?", "\"I saw them but thought they were part of the packaging. I didn't realize they showed it wasn't bought.\""), .direct("What did you want from the return?", "\"Just store credit I could use on things I needed. I wasn't trying to get cash or cheat anyone.\""), .direct("What happened at the desk?", "\"They asked questions I couldn't answer, and I told them the same thing I'm telling you. I never left the store.\""), .direct("What do you understand now?", "\"That I should have asked my friend where it came from before I brought it anywhere near a return desk.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I know better than to bring a return like that. I should have left it alone.\""), .cross("The receipt wasn't for that set?", "\"No, it was for something else, and I didn't check. I should have, and I'm sorry.\""), .cross("The security tags were still on?", "\"Yes, and I should have noticed. A bought item wouldn't have had them on.\""), .cross("You asked for two hundred twelve dollars of credit?", "\"Yes, that's the value on the set. I thought the return would be simple.\""), .cross("You can't prove it was a gift?", "\"Not with a paper receipt. I only have my friend's word, and I should have asked for more.\"")],
        openings: ("{D} tried to return a set of cookware at another store with a receipt for a different purchase on a different day. The security tags were still on the pans, and {DL} had stood in this court in {PRIORDATE} over {PRIOR}.", "The defense will say the cookware was a gift and the receipt was the only paper that came with it. {D} did not know the receipt was wrong, and returned it in good faith."),
        closings: ("The receipt listed other items, the tags were still on the cookware, and {D} had been here over {PRIOR} already. A real purchase does not arrive with the wrong receipt and the tags intact.", "A gift comes without a proper receipt, and a person who gets one may reach for any paper at hand. {D} did not lie about the cookware, and the State must prove {D} knew it was not bought."),
        timeline: [(0, "Midday: the return."), (0, "Loss prevention stops {DL}.")],
        identified: "Loss prevention's check.",
        genders: ["D": .female])

    static let fakeLicenseBar = SmallCases.make(
        key: "story.followup.fakeLicenseBar",
        category: .whiteCollar,
        headlines: ["Underage Man Tries Fake License at Bar", "Bouncer Spots Forged ID"],
        law: "uttering",
        spec: "Uttered a forged driver's license at a bar, on {DATE}.",
        ages: 18...22,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} presented a fake license at a bar. A bouncer noticed the hologram was wrong and called deputies.",
        state: [E(.physical, 3, "The License", "A forged license with a bad hologram.", .search), E(.video, 2, "Door Camera", "{D} hands the license to the bouncer.")],
        defense: [E(.statement, 1, "Found ID", "{DL} says {D.he} found it.")],
        role: "Bar doorman",
        exam: [.direct("What were you doing at the door that night?", "\"I was checking IDs at the entrance, and I check every license under the light and with a black-light pen.\""), .direct("What did {DL} hand you?", "\"A driver's license that looked normal at a glance, but the hologram was off when I tilted it.\""), .direct("What was wrong with it?", "\"The hologram didn't shift the way a real one does, the print was slightly blurry, and the font was wrong.\""), .direct("What does the door camera show?", "\"It shows {DL} handing the card to me, me checking it twice, and then me calling the deputies.\""), .direct("What did you do next?", "\"I kept the license, told {DL} to wait, and called the sheriff's office because it's the policy for a forged ID.\""), .direct("What did {DL} say?", "\"{D.He} said {D.he} had found the card and used it to get in without thinking.\""), .cross("{DL} didn't argue with you?", "\"No. {D.He} stayed calm, said little, and waited for the deputies.\""), .cross("{DL} didn't try to leave?", "\"No, {D.he} stayed where {D.he} was until deputies arrived.\""), .cross("You can't say who made the card?", "\"No. I just know it wasn't a real license. I don't know who printed it.\""), .cross("{DL} hadn't bought a drink yet?", "\"No. {D.He} never got past the door, so nothing was served.\""), .cross("Many fake IDs look this good?", "\"Some look very good. This one was caught only because of the hologram.\"")],
        theory: ("{D} used another forged license.", "A found ID."),
        allocution: "\"I'll wait until I'm twenty-one. I found that ID and used it to get into the bar, and I knew it wasn't mine. It was stupid and I'm sorry. I've been in this courtroom before, and I won't try it again.\"",
        truths: ("{DL} had ordered a second license after the first was taken.", "The license had {DL}'s face on it."),
        defendant: [.direct("Where did you get the license?", "\"I found it on the ground near my apartment a few weeks ago. It had a picture that looked a bit like me.\""), .direct("Why did you use it at the bar?", "\"I wanted to get into a place where my friends were going, and I thought nobody would look closely.\""), .direct("Did you know it was fake?", "\"I suspected it wasn't real, but I didn't know for sure. I should have thrown it away.\""), .direct("What happened at the door?", "\"The doorman looked at it twice and called the deputies. I stayed where I was and told them the truth.\""), .direct("Why did you hand over the card at all?", "\"I wasn't thinking. I wanted to go in with my friends, and I didn't think about what could happen.\""), .direct("What would you do differently?", "\"I'd give back the card or throw it out, and I would use my own license or stay home.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I knew how serious it is to hand over a fake license. I made a bad decision.\""), .cross("You used a card that wasn't yours?", "\"Yes. I found it and used it, and I know that's wrong.\""), .cross("The doorman noticed the hologram?", "\"Yes, he did, and I'm glad he caught it before I got in.\""), .cross("You didn't turn the card in when you found it?", "\"No, I kept it. I should have taken it to the sheriff's office.\""), .cross("You'll stay away from fake IDs?", "\"Yes. I don't plan to use another one. I'll use my real license and follow the rules.\"")],
        openings: ("At the door of a bar {D} handed the bouncer a license whose hologram was wrong, and the bouncer called deputies. The door camera shows the hand-off, and {DL} had already appeared here in {PRIORDATE} over {PRIOR}.", "The defense will say {D} found the license and used it without knowing it was not genuine. {D} did not make it, did not pay for it, and gave it up when the bouncer spotted the flaw."),
        closings: ("A forged license, handed over at a bar door, by a person who had already been here over {PRIOR}. The bouncer checks every ID with a black-light pen, and the hologram was wrong.", "A found card handed over once is not proof that {D} knew it was fake. The State must show {D} knew the license was forged, and nothing shows {D} ever made one."),
        timeline: [(0, "10 p.m.: {DL} at the bar's door."), (0, "The bouncer calls deputies.")],
        identified: "The bouncer's call.",
        genders: ["D": .male])

