        defense: [E(.statement, 1, "Job", "{DL} says {D.he} was on a job and the foreman owed {D.him} for tools.")],
        role: "Home improvement store manager",
        exam: [.direct("What drew your attention to {DL}?", "\"A guard watching the floor saw {DL} put tools into a bag in the tools aisle and walk toward the exit.\""), .direct("What does the store camera show?", "\"It shows {DL} filling a bag with tools, passing every register, and leaving through the front door.\""), .direct("What was in the bag?", "\"About two hundred fifty-six dollars of tools, including a drill bit set, a hammer, and a tape measure.\""), .direct("How was {DL} stopped?", "\"A security guard stopped {D.him} at the exit, asked for a receipt, and held {D.him} until deputies came.\""), .direct("What did the loss report show?", "\"It showed two hundred fifty-six dollars of tools unpaid, matched by item to the shelf and the bag.\""), .direct("What did {DL} say?", "\"{D.He} said {D.he} was working a job and that the foreman owed {D.him} for tools.\""), .cross("{DL} wasn't trying to hide the bag?", "\"The bag was in plain sight, but {D.he} didn't stop at any register.\""), .cross("{DL} didn't run when stopped?", "\"No. {D.He} stopped when the guard spoke to {D.him} and stayed calm.\""), .cross("You don't know about any dispute with a foreman?", "\"No, I don't. I only know what {D.he} told me at the exit.\""), .cross("The tools were recovered?", "\"Yes, everything in the bag was returned to our shelves.\""), .cross("{DL} didn't take anything else?", "\"The bag held only the tools, and the guard didn't find anything else on {D.him}.\"")],
        theory: ("{D} stole tools after the paint case.", "A worker owed for tools."),
        allocution: "\"My foreman owed me for work, and I took those tools out of the store thinking that squared it. It doesn't, and I'm sorry. I've been in this courtroom before, and I should have gone through the proper channels. I'll cover the two hundred fifty-six dollars.\"",
        truths: ("{DL} sold the tools to a pawn shop within the hour.", "The foreman confirmed owing {DL} for tools."),
        defendant: [.direct("Why did you take the tools?", "\"I was on a job and the foreman owed me for tools I'd bought myself, so I thought I could make it even.\""), .direct("Why didn't you pay for them?", "\"I thought I'd settle it with the foreman afterward. I didn't think about how it would look at the register.\""), .direct("Did you try to hide what you were doing?", "\"I didn't think of it as hiding. I put them in my bag and walked out, which was a mistake.\""), .direct("What happened when the guard stopped you?", "\"I told the guard exactly what I told you and put the bag down. I didn't try to leave.\""), .direct("What have you done since?", "\"I paid the store back for any loss, and I told the foreman we're even and I won't take tools again.\""), .direct("What do you understand now?", "\"That I should have asked the foreman for money or gone to the labor office instead of taking things.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, over the earlier case, and I knew better than to take anything from a store.\""), .cross("You walked past every register?", "\"Yes, I did, and I know that's the mistake. I wasn't thinking about the law.\""), .cross("The foreman never agreed that you could take the tools?", "\"No, he didn't, and I understand that I can't make my own rules.\""), .cross("You concealed the tools in a bag?", "\"They were in my bag, yes. It looked like hiding them, and I'm sorry it did.\""), .cross("The tools were worth over two hundred dollars?", "\"Yes, and I should have thought about that before I walked out.\"")],
        openings: ("A security guard watched {D} fill a bag with $256 of tools and walk past every register at a different store, and stopped {DL} at the exit. {DL} came before this court in {PRIORDATE} over {PRIOR}, the paint cans.", "The defense will present a worker who was on a job and believed the foreman owed {D.him} for tools {D.he} had bought himself. {D.He} did not hide the tools and walked out the front door in view."),
        closings: ("The store camera shows {D} filling a bag, passing every register, and leaving, with $256 of tools unpaid. After {PRIOR}, {DL} knew this was theft.", "A worker owed for tools who walked out in plain view did not act like a thief. {D} believed {D.he} had a claim to the tools, and the State must prove {D} meant to take what was not {D.his}."),
        timeline: [(0, "Midday: the tools go into the bag."), (0, "The guard stops {DL}.")],
        identified: "The store's camera.",
        genders: ["D": .male])

    static let dumpsterFireTwo = SmallCases.make(
        key: "story.followup.dumpsterFireTwo",
        category: .property,
        headlines: ["Second Dumpster Fire Behind Same Restaurant", "Fire Marshal Says Fire Was Set"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, a commercial dumpster, by fire, causing damage of $1,100, on {DATE}.",
        ages: 19...50,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, another dumpster fire started behind {V}'s restaurant. A hooded figure appeared on camera again. {D} says {D.he} was nowhere near.",
        state: [E(.video, 3, "Kitchen Camera", "A hooded figure lights a rag and drops it in."), E(.document, 2, "Fire Marshal's Report", "Same method as the earlier fire.")],
        defense: [E(.statement, 1, "Alibi", "{DL}'s girlfriend says {D.he} was home.")],
        role: "County fire marshal",
        exam: [.direct("What did you find at the restaurant?", "\"A commercial dumpster behind the building had burned, the lid was warped, and the wall nearby was scorched.\""), .direct("What does the kitchen camera show?", "\"A hooded figure lights a rag, drops it into the dumpster, and walks off in the direction of the alley.\""), .direct("How did you tell it was set?", "\"There was a charred rag near the point of origin, and the burn pattern started at the lid, not inside.\""), .direct("Why did you compare it with the earlier fire?", "\"The method was the same: a lit rag dropped in at night, and the hooded figure walked the same way.\""), .direct("What was the damage?", "\"About eleven hundred dollars for the dumpster and a section of damaged siding, plus the fire department response.\""), .direct("What did {DL} say?", "\"{D.He} said {D.he} was nowhere near, and that {D.his} girlfriend would say {D.he} was home that night.\""), .cross("The figure's face isn't visible?", "\"No. The hood covers it, and the camera sits too far away to see features.\""), .cross("You can't say how tall or heavy the person is?", "\"Only that it's an average build. I can't say much more from that video.\""), .cross("{DL}'s girlfriend says {D.he} was home?", "\"That's what {D.he} told me, and I've not been able to disprove it with other evidence.\""), .cross("No one saw {DL} near the restaurant?", "\"No witness has placed {D.him} there that night.\""), .cross("You didn't recover anything with {DL}'s prints?", "\"That's right. The rag was too burned to test for fingerprints.\"")],
        theory: ("{D} did it again.", "A hood and an alibi."),
        allocution: "\"I'll pay, if it comes to that, but I wasn't there that night. I was nowhere near that restaurant, and I know I was fired from there. I've been in this courtroom before, and I know that makes me look guilty. I'm sorry for the damage, and I hope you find who did it.\"",
        truths: ("{DL}'s lighter was found in a trash can near the restaurant.", "The figure's gait matched a delivery driver."),
        defendant: [.direct("Where were you that night?", "\"I was at home with my girlfriend. We watched television and I fell asleep on the couch before midnight.\""), .direct("Do you know anything about the fire?", "\"No. I heard about it later from the deputy. I had nothing to do with it and don't know who did.\""), .direct("Do you own a hooded sweatshirt?", "\"I do, like most people, but I wasn't wearing it that night and I wasn't at the restaurant.\""), .direct("Why would the deputies look at you?", "\"Because of the earlier case, I guess. I understand why, but that doesn't mean I did this one.\""), .direct("What did you do when the deputy came?", "\"I answered every question and offered my girlfriend's name so the deputy could talk to her.\""), .direct("What would you tell the court?", "\"I didn't set that fire. I'd ask the court to look for the real person and not just the one with a record.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I understand how it looks. That doesn't change that I was at home.\""), .cross("Your girlfriend is your only alibi?", "\"She is, but she was with me the whole night and she's willing to say so.\""), .cross("The earlier fire was set the same way?", "\"So I've been told. I had nothing to do with that one either, and I told the court so.\""), .cross("You've been angry at that restaurant?", "\"No. I've never had any problem with them. I've eaten there with my family.\""), .cross("You can't prove you were at home?", "\"Other than my girlfriend, no, but that's the truth and I'd ask the court to believe it.\"")],
        openings: ("Another dumpster burned behind {V}'s restaurant, and the kitchen camera shows a hooded figure light a rag and drop it in. The fire marshal says the method matches the earlier fire, and this was not {DL}'s first time here, after {PRIOR} in {PRIORDATE}.", "The defense will present {D}'s girlfriend, who says {D.he} was home that night. The hood hides the face on the camera, and no one has named who lit the rag."),
        closings: ("Same method, same dumpster, same restaurant, and {D} was back after {PRIOR}. The marshal's report ties this fire to the earlier one and to {D}.", "A hood and a rag point to no one in particular, and {D}'s girlfriend places {D.him} at home. The State cannot show who was under the hood."),
        timeline: [(0, "2 a.m.: the second fire."), (0, "2:05 a.m.: the fire is out.")],
        identified: "The kitchen camera.",
        impact: "That was twice in a month that a fire started behind my restaurant, and the second time I was sure someone was trying to hurt us. The fire department came again, and my cooks were scared to take out the trash. I want to feel safe closing up at night.")

    static let cashBoxCafe = SmallCases.make(
        key: "story.followup.cashBoxCafe",
        category: .property,
        headlines: ["Cash Box Taken From Coffee Shop Counter", "Second Counter Theft at Same Shop"],
        law: "misdLarceny",
        spec: "Stole $140 in cash from a cash box belonging to {V}, a coffee shop, on {DATE}.",
        ages: 18...50,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} returned to the same coffee shop and took the cash box from the counter. Staff recognized {DL} from the earlier case.",
        state: [E(.video, 3, "Shop Camera", "{D} lifts the cash box and leaves."), E(.document, 2, "Till Count", "$140 short.")],
        defense: [E(.statement, 1, "Found", "{DL} says the box was on a bench outside.")],
        role: "Coffee shop owner",
        exam: [.direct("What did you notice on the morning of the theft?", "\"The cash box that normally sits behind the counter was gone, and the register tape showed a hundred forty dollars short.\""), .direct("What does the shop camera show?", "\"It shows {DL} come in, lift the cash box from the counter while no one was looking, and walk out.\""), .direct("How did you recognize {DL}?", "\"{D.He} had been in the shop during the earlier case, and my staff and I knew {D.him} on sight.\""), .direct("What was in the box?", "\"About a hundred forty dollars in small bills and coins, which was the float and the morning's tips.\""), .direct("Was the money recovered?", "\"No. The money was never returned, though we got the box back when it was found outside.\""), .direct("What did {DL} say?", "\"{D.He} said the box was sitting on a bench outside and {D.he} picked it up and thought it was abandoned.\""), .cross("The box is normally behind the counter, isn't it?", "\"Yes, but on busy mornings it's kept on the counter near the register.\""), .cross("You didn't see {DL} take it?", "\"I was in the back. I saw it on the camera afterward and didn't watch it happen.\""), .cross("The box was found outside later?", "\"Yes, someone found it near the bench a short time after, empty.\""), .cross("{DL} didn't try to hide from the camera?", "\"No. {D.He} walked in as usual, and I can't say whether {D.he} noticed the camera.\""), .cross("{DL} has been a customer before?", "\"Yes, {D.he} came in occasionally, which is how my staff recognized {D.him}.\"")],
        theory: ("{D} took cash from the same shop twice.", "A box on a bench."),
        allocution: "\"I'll never go back to that coffee shop. I found that box on a bench and took it, and I'm sorry. I knew the staff recognized me from the earlier case, and I should have known better. I'll repay what was in it.\"",
        truths: ("{DL} had asked a barista what time the shop closed.", "The cash box was on the counter and the barista was in the back."),
        defendant: [.direct("Did you take the cash box?", "\"I picked up a box from a bench outside, thinking it was left behind, and I walked off with it.\""), .direct("Why did you think it was abandoned?", "\"It was sitting alone on a bench and I didn't see anyone near it. I didn't think it belonged to the shop.\""), .direct("Did you go inside the shop?", "\"I went in to ask if anyone had lost a box, but no one was at the counter and I left.\""), .direct("What did you do with the box?", "\"I opened it, saw the cash, and took it. I know I should have handed the whole thing in.\""), .direct("Why did you take the money?", "\"I was short on rent, and I told myself that if no one claimed it, it was fair for me to keep.\""), .direct("What would you say to the shop's owner?", "\"I'm sorry. I'll pay back the hundred forty dollars, and I won't come back to the shop unless you want me to.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I should have known that taking cash from a shop is wrong, no matter where the box was.\""), .cross("The camera shows you lifting it from the counter?", "\"It does, and I can't argue with the video. I should have been honest about that from the start.\""), .cross("You took money that wasn't yours?", "\"Yes. I did that, and I regret it more than I can say. I let the rent worry make a bad choice for me.\""), .cross("You told the deputy it was on a bench?", "\"I did, and that wasn't the whole truth. I'm sorry I wasn't honest about it.\""), .cross("You'll repay the shop?", "\"Yes, in full, as soon as the court lets me, and I'll apologize to the owner.\"")],
        openings: ("{D} came back to the same coffee shop where {DL} was known from the earlier case over {PRIOR}, and the shop camera shows {D} lift the cash box from the counter and leave. The till was $140 short.", "The defense will say the box was sitting on a bench outside when {D} saw it. {D} picked up what looked abandoned, and did not take anything from behind the counter."),
        closings: ("The cash box normally sits behind the counter, the camera shows {D} lifting it from there, and the till was $140 short. {DL} was recognized from {PRIOR}, and knew the shop.", "A box on a bench is not the same as a box behind the counter, and {D} saw an unattended box outside. The State must show {D} took it knowing it belonged to the shop."),
        timeline: [(0, "Afternoon: the cash box is taken."), (0, "The barista recognizes {DL}.")],
        identified: "The shop's camera and a barista's memory.",
        impact: "I'm shorter staffed now because I can't afford another loss. We run on small margins, and the cash box covered a week of tips and change. I recognized the man at the counter from the last time. I felt sick when I saw the empty spot.",
        genders: ["D": .male])

    static let shedBreakInTwo = SmallCases.make(
        key: "story.followup.shedBreakInTwo",
        category: .property,
        headlines: ["Shed Broken Into Again, Tools Taken", "Neighbor's Shed Hit Twice"],
        law: "feloniousBE",
        spec: "Broke and entered a building, a backyard storage shed belonging to {V}, with intent to commit larceny therein, on {DATE}.",
        ages: 19...55,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V}'s shed was broken into again. A drill taken from the shed was found in {D}'s garage.",
        state: [E(.physical, 3, "The Drill", "{V}'s drill with an etched name, in {D}'s garage.", .search), E(.physical, 2, "Pry Marks", "New pry marks on a new lock.")],
        defense: [E(.statement, 1, "Yard Sale", "{DL} says {D.he} bought the drill at a yard sale.")],
        role: "Sheriff's deputy",
        exam: [.direct("What were you called to that day?", "\"{V} reported that the shed behind the house had been broken into again and that a drill was missing.\""), .direct("What did you find at the shed?", "\"A new lock was pried off, with fresh pry marks on the hasp and door frame, and tools were out of place inside.\""), .direct("What was taken?", "\"{V}'s cordless drill, which had {V.his} name etched in the case, along with a few smaller hand tools.\""), .direct("How did the drill turn up?", "\"A tip led deputies to {DL}'s garage, where we found the drill in plain view on a shelf with the etched name on it.\""), .direct("Did you have a warrant?", "\"Yes. We searched under a warrant and photographed the drill where it sat before taking it into evidence.\""), .direct("What did {DL} tell you?", "\"{D.He} said {D.he} bought the drill at a yard sale and had no idea whose it was.\""), .cross("{DL} didn't hide the drill?", "\"No. It was on a shelf in an open garage where anyone could have seen it.\""), .cross("You can't say when the drill was taken?", "\"Only that it was in the shed the day before and gone the next morning.\""), .cross("Yard sales are common around there?", "\"Yes, especially on weekends, and tools do turn up for sale at them.\""), .cross("Nothing else from the shed was in {DL}'s garage?", "\"No. The drill was the only item we found that matched anything reported.\""), .cross("{DL} cooperated with the search?", "\"Yes, {D.he} let us in without argument and answered our questions.\"")],
        theory: ("{D} returned to the same shed and took the drill.", "A yard sale buy."),
        allocution: "\"I'll return everything. I bought that drill at a yard sale, and I never broke into anybody's shed. I know it was found in my garage, and I know about my history in this courtroom. I'm sorry to {V}, and I'll make it right.\"",
        truths: ("{DL}'s truck was on camera again.", "The seller later confirmed selling {DL} the drill."),
        defendant: [.direct("Where did you get the drill?", "\"I bought it at a yard sale a few weeks ago from a man who said he was clearing out his father's tools.\""), .direct("How much did you pay?", "\"Fifteen dollars. It seemed cheap, but the man said he wanted it gone, and I didn't think more about it.\""), .direct("Did you see the name on the case?", "\"I noticed some scratches but didn't read the name. I thought it was wear from use.\""), .direct("Did you break into {V}'s shed?", "\"No. I never went to {V.his} property and had no reason to. I didn't know whose tools those were.\""), .direct("What did you do when the deputy found it?", "\"I told the deputy where I bought it and offered to show where the yard sale was held.\""), .direct("What would you tell the court?", "\"I'm sorry that {V} lost the drill. I bought it honestly, and I'd ask the court to see that.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and that's why I should have looked more closely at what I was buying.\""), .cross("The drill had {V}'s name etched on it?", "\"Apparently so, and I should have noticed. I just didn't look.\""), .cross("You can't name the man who sold it?", "\"I never got a name. I only know the street where the sale was.\""), .cross("You paid fifteen dollars for a drill worth much more?", "\"Yes, and I know that should have raised a question. I didn't ask it.\""), .cross("You'll return the drill to {V}?", "\"Yes. I'd like to see it returned and to pay whatever the court thinks is fair.\"")],
        openings: ("{V}'s shed was broken into again, with fresh pry marks on a new lock, and a drill taken from the shed turned up in {D}'s garage. {DL} came before this court in {PRIORDATE} over {PRIOR}, the earlier break-in at the same shed.", "The defense will say {D} bought the drill at a yard sale like any bargain hunter. {D} did not know the drill was {V}'s, and was never at the shed."),
        closings: ("The same shed, a new lock, new pry marks, and {V}'s drill in {D}'s garage. After {PRIOR}, {DL} knew whose shed this was, and had the drill.", "Many drills look alike, and a yard sale is where a buyer finds one. The pry marks do not identify {D}, and the State must prove {D} knew the drill came from the shed."),
        timeline: [(0, "2 a.m.: the shed is forced."), (3, "A deputy finds the drill.")],
        identified: "A deputy's search.",
        impact: "The second lock didn't help. I'd already replaced the first one after the break-in, and they got through the new one anyway. The drill was a gift from my father. I keep a flashlight by the window now and walk out to the shed every night.",
        genders: ["D": .male])

    static let scaleAgain = SmallCases.make(
        key: "story.followup.scaleAgain",
        category: .drugs,
        headlines: ["Scale and Bags Found Again in Car", "Second Paraphernalia Charge for Jewelry Seller"],
        law: "possParaphernalia",
        spec: "Knowingly possessed drug paraphernalia, a digital scale, on {DATE}.",
        ages: 19...45,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} was stopped again and a digital scale with residue was found. The lab found cocaine residue this time.",
        state: [E(.forensic, 3, "Lab Report", "Cocaine residue on the scale.", .search), E(.physical, 2, "The Scale", "A digital scale in the console.")],
        defense: [E(.statement, 1, "Beads", "{DL} says {D.he} still sells jewelry.")],
        role: "Sheriff's deputy",
        exam: [.direct("What led to the stop?", "\"I stopped {DL}'s vehicle for a traffic violation, and during the stop I noticed an item in the center console.\""), .direct("What did you find?", "\"A digital scale in the console with a white powdery residue visible on the weighing surface.\""), .direct("What did the lab report say?", "\"The State Crime Lab found cocaine residue on the scale, which is a controlled substance in this state.\""), .direct("Why does a scale like that matter?", "\"Scales are used to weigh drugs for sale or use, and residue on one points to drug handling.\""), .direct("Where exactly was the scale?", "\"In the center console, within reach of the driver's seat, in plain view when I opened the lid.\""), .direct("What did {DL} say about the scale?", "\"{D.He} said {D.he} still sells jewelry and uses the scale to weigh beads and silver.\""), .cross("Jewelers do use digital scales, don't they?", "\"Yes, they do. A small scale is a normal tool for people who sell beads and silver.\""), .cross("There were no drugs in the car?", "\"None. Only the scale had residue, and nothing else tested positive.\""), .cross("{DL} was cooperative during the stop?", "\"Yes, {D.he} was polite and answered questions, and didn't try to hide anything.\""), .cross("The residue was small?", "\"The lab reported it as residue, not as a quantity, so it was a very small amount.\""), .cross("You can't say when the residue got there?", "\"No. The lab can't date it, so I can't say whether it was last week or last year.\"")],
        theory: ("{D} had a scale with cocaine residue.", "A jewelry scale borrowed from a friend."),
        allocution: "\"That scale is mine, and I don't know how residue got on it. I've been in this courtroom before, and I know it counts against me. I'm sorry for the trouble, and I'll take whatever help or conditions the court sets.\"",
        truths: ("{DL}'s texts mentioned grams again.", "{DL}'s friend borrowed the car and used the scale."),
        defendant: [.direct("Why did you have a scale in the car?", "\"I sell handmade jewelry at weekend markets, and the scale weighs beads and silver wire for my pieces.\""), .direct("Do you know how cocaine got on it?", "\"I don't. A friend borrowed the scale once, and I didn't clean it well after. I never used it for drugs.\""), .direct("Have you ever sold drugs?", "\"No. I've made mistakes before, but I stopped, and I haven't dealt with drugs since the last case.\""), .direct("What happened at the stop?", "\"The deputy asked about the scale, I told him what it was for, and he took it. I didn't resist.\""), .direct("What have you changed since the last case?", "\"I've stayed away from the people who were in my life then and put my time into my jewelry and my job.\""), .direct("What would you tell the court?", "\"The scale is for beads. I'm trying to live straight, and I'd ask the court to look at my work and my life.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, over drugs, and I know why that makes this look worse. I'm telling the truth now.\""), .cross("Cocaine was found on your scale?", "\"The lab says so, and I can't explain it except that someone must have used it when I wasn't looking.\""), .cross("You keep it in the console of your car?", "\"Yes, because I go from market to market and need it with me. I should have cleaned it more carefully.\""), .cross("You've used cocaine before?", "\"In the past, yes, and I've worked to stay clear of it. I haven't used in a long time.\""), .cross("You'll get rid of the scale?", "\"I'll buy a new one and keep it in a locked case, so that this can't happen again.\"")],
        openings: ("Deputies stopped {D} again and found a digital scale in the console with white residue on the surface, and the lab found cocaine on it, and {DL} had faced this court in {PRIORDATE} over {PRIOR}.", "The defense will say the scale is for jewelry, which {D} still sells, and that {D} borrowed it from a friend. A jeweler's scale in a console is not evidence of anything else."),
        closings: ("Residue on a scale in the console, within {D}'s reach, after the earlier case over {PRIOR}. The lab confirms cocaine, and the scale was in {D}'s vehicle.", "A jewelry scale borrowed from a friend can carry residue from someone else's use. {D} did not know what was on it, and the State must prove otherwise."),
        timeline: [(0, "Evening: a stop for a taillight."), (0, "The scale is seized.")],
        identified: "A traffic stop.",
        doctrines: ["searchSeizure", "burdenOfProof"])

    static let airsoftSchoolLot = SmallCases.make(
        key: "story.followup.airsoftSchoolLot",
        category: .violent,
        headlines: ["Airsoft Pistol Pointed at Boys in School Lot", "Toy Gun Pointed Again, Deputies Say"],
        law: "assaultPointingGun",
        spec: "Assaulted {V} by pointing a gun, an airsoft pistol that appeared to be a handgun, on {DATE}.",
        ages: 18...40,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} pointed an airsoft pistol at {V}, a high school student, in a school parking lot after a dispute over a parking space.",
        state: [E(.physical, 3, "The Pistol", "An airsoft pistol with the orange tip removed.", .search), E(.statement, 2, "{V}", "{V} says it looked like a real pistol.")],
        defense: [E(.statement, 1, "Toy", "{DL} says it was a toy and everyone knows it.")],
        role: "School resource officer",
        exam: [.direct("What were you called to that afternoon?", "\"A student told me that someone had pointed a gun at {V} in the school parking lot after a dispute over a space.\""), .direct("What did {V} tell you?", "\"{V} said the driver pulled a pistol and pointed it at {V.him}, and {V.he} thought it was a real gun.\""), .direct("What did you find on {DL}?", "\"An airsoft pistol in the driver's door pocket with the orange safety tip removed, which makes it look like a real handgun.\""), .direct("Why is the orange tip important?", "\"It's the marking that tells people a replica isn't a firearm. Without it, the pistol looks exactly like the real thing.\""), .direct("How did {V} react?", "\"{V} was shaken and said {V.he} froze when the pistol was pointed and thought {V.he} was about to be shot.\""), .direct("What did {DL} say?", "\"{D.He} said it was a toy, that everyone knows it's an airsoft gun, and that {D.he} was only making a point.\""), .cross("The pistol was an airsoft pistol, not a firearm?", "\"Yes, I confirmed that. It fires plastic pellets and isn't a firearm under the statute.\""), .cross("There was no threat spoken?", "\"{V} told me nothing was said about shooting. The pistol was pointed, and that was what frightened {V.him}.\""), .cross("{DL} didn't fire it?", "\"No. {V} didn't hear a shot, and no pellet was found on the ground.\""), .cross("The two were arguing over a parking space?", "\"Yes, that was the dispute reported by both of them.\""), .cross("{DL} gave you the pistol right away?", "\"Yes, {D.he} handed it over when I asked, and didn't resist at all.\"")],
